-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(2, { "classic", "forever" }, { deDE = { progress = "Ja, {class}, ich habe Eure Ankunft bereits gespürt. Habt Ihr weitere Neuigkeiten von Eurer Jagd zu berichten?", completion = "Wirklich beeindruckend, {name}... Die Klaue von Scharfkralle dürfte nicht einfach zu bekommen gewesen sein. Die Jagd in Ashenvale läuft gut für Euch!\n\nScharfkralle hat über lange Zeit hinweg die Peons aus den Holzfällerlagern entlang seinem Weg terrorisiert, wenn diese versuchten, hierher zum Splintertreeposten zu gelangen. Zweifelsohne werden viele begeisterte Lieder über Eure Tapferkeit an den Lagerfeuern und in den Holzfällerlagern überall in Ashenvale erschallen, sobald man davon hört, dass Ihr es wart, der die Bestie bezwungen hat." }, enUS = { progress = "Yes, mighty {class}, I sensed your arrival.  I trust you have more news to report to me about your hunt?", completion = "Most impressive, {name}... the claw of Sharptalon could not have been easy to get!  The Ashenvale Hunt goes well for you!\n\nSharptalon had long terrorized the peons from the lumber camps near its path as they tried to travel here to Splintertree Post.  No doubt once the word gets out that it was you who put down the beast, many rousing songs of your bravery will be heard at campfires and lumber mills across Ashenvale!" } })
apply(5, { "classic", "forever" }, { deDE = { completion = "Ihr braucht einige Krebsküchlein, wie? Na ja, ich könnte Euch vielleicht ein paar machen." }, enUS = { completion = "You need some Crab Cakes, do you?  Well I might be able to cook some up for you..." } })
apply(6, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Garricks Schuppen gefunden? Sind wir diesen Schurken endlich los?", completion = "Ha, Ihr habt ihn erwischt! Ihr habt ganz Elwynn einen großen Dienst erwiesen und Euch ein schönes Kopfgeld verdient!" }, enUS = { progress = "Did you find Garrick's shack?  Are we finally free of that villain?", completion = "Hah - you caught him!  You've done Elwynn a great service, and earned a nice bounty!" } })
apply(7, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, Bürger. Diese Kobolde sind Diebe und Feiglinge, aber wenn sie in Massen auftreten, dann sind sie doch eine Gefahr für uns. Und die Menschen von Stormwind können nun wirklich keine weitere Gefahr gebrauchen.\n\nHabt meinen Dank dafür, dass Ihr sie besiegtet!" }, enUS = { completion = "Well done, citizen.  Those kobolds are thieves and cowards, but in large numbers they pose a threat to us.  And the humans of Stormwind do not need another threat.\n\nFor defeating them, you have my gratitude." } })
apply(8, { "classic", "forever" }, { deDE = { progress = "Ja? Ja? Was ist?\n\nFür ein Volk von Wesen, die unter Wasser nicht atmen müssen, haben sie schon einen sehr gesunden Appetit. Fühlt Euch ganz wie zu Hause, fühlt Euch ganz wie zu Hause. Ich heiße Renee, falls Ihr irgendetwas braucht.", completion = "Ach? Ein Brief? Wie schön! Ich warte schon seit langem darauf, wieder einmal etwas von meiner lieben alten Mutter in Deathknell zu hören. Sie ist ja eine so wunderbare Person! Ich frage mich, wie die Gute so zurechtkommt.\n\nWas? Zu fröhlich? Ihr kauft mir das nicht ab, wie?\n\nNa, dann verschwindet. Es geht Euch sowieso rein gar nichts an, von wem dieser Brief ist. Na los! Verschwindet schon!\n\nKommt wieder, sobald Ihr 'n bisschen Geld habt, das Ihr ausgeben könnt, Faulenzer.\n\nSonst kommt Ihr als Nächstes noch her und wollt Euch nach einem langen Tag des Abenteuerns hier ausruhen oder so'n Quark." }, enUS = { progress = "Yes? Yes? What is it?\n\nThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name's Renee if you need anything at all.", completion = "Oh? A letter? Wonderful news! I've been waiting on word from my dear old mother in Deathknell. Such a saint, she is. I wonder how she's holding up.\n\nWhat? Too cheery? Not buying it, are you?\n\nWell, get lost then... it's really no business who the letter's from anyway. Go on! Get lost!\n\nCome back when you've got some coin to spend... loafer.\n\nNext thing you know, you'll be coming back to rest after a long days adventure or some stupid thing like that." } })
apply(9, { "classic", "forever" }, { deDE = { progress = "Ah, wie ich sehe, seid Ihr wieder da! Ich hoffe doch sehr, dass Ihr fleißig wart und die Felder von diesen Erntebehütern gesäubert habt. Habt Ihr schon 20 getötet?", completion = "Gute Arbeit, mein Freund. Ihr habt Euch Eure Bezahlung redlich verdient. Wer weiß, vielleicht wird Westfall ja wieder aufblühen." }, enUS = { progress = "Ah, I see you're back!  I hope you've been hard at work clearing those fields of those Harvest Watchers.  Have you killed twenty yet?", completion = "Good work, friend.  You have earned your pay well.  Who knows, perhaps Westfall will prosper once again." } })
apply(10, { "classic", "forever" }, { deDE = { progress = "Nun, was habt Ihr für Neuigkeiten? Ihr seht aus, als hättet Ihr einiges durchgemacht... ist Scrimshank am Leben?", completion = "Er war ein guter Goblin, der junge Scrimshank. Hoffen wir, dass sein Ableben durch das, was er mit seiner Feldmesserausrüstung aufzeichnen konnte, nicht umsonst war.\n\nEs scheint als wären wir mit diesen Viechern in eine ziemlich unangenehme Lage geraten. Sie sind viel zu gerissen und unsere bisherigen Forschungen deuten an, dass sie sich möglicherweise sogar unter dem kontrollierenden Einfluss eines Dritten befinden! Wenn das stimmt, ist das nicht nur für Gadgetzan ein schlechtes Zeichen, sondern für die ganze Wüste!" }, enUS = { progress = "Well, what news do you have?  You look like you've been in quite the fight... is Scrimshank alive?", completion = "He was a good goblin, young Scrimshank.  Let's hope that his demise was not in vain by what he was able to record with his surveying equipment.\n\nIt seems as though we have quite the situation on our hands here with these bugs.  They're way too cunning for their own good, and the research we've done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!" } })
apply(11, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Wart Ihr Gnolle töten?", completion = "Wie ich sehe, wart Ihr fleißig! Habt Dank, {name}." }, enUS = { progress = "Hail, {name}.  Have you been killing Gnolls...?", completion = "I see you've been busy!  You have our thanks, {name}." } })
apply(12, { "classic", "forever" }, { deDE = { progress = "Vielleicht habe ich mich nicht klar genug ausgedrückt, Kandidat. Um Euren Wert als Diener der Volksmiliz und Diener des Lichtes zu beweisen, müsst Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias erschlagen und zu mir zurückkehren, sobald Ihr dies getan habt.", completion = "Gut gemacht, {name}. Mein Späher hat Eure tapferen Taten beobachtet. Bis jetzt bewährt Ihr Euch recht gut." }, enUS = { progress = "Perhaps I did not make myself clear, pledge.  In order to prove your worth as a servant to The People's Militia and to the Light you need to slay 15 Defias Trappers and 15 Defias Smugglers then return to me when the deed is done.", completion = "Well done, {name}.  My scout witnessed your valiant acts.  You are proving yourself quite well so far." } })
apply(13, { "classic", "forever" }, { deDE = { progress = "Wir haben jetzt keine Zeit für Geschwätz, {name}! Die Plünderer der Defias hindern die Bewohner von Westfall daran, den Frieden und Wohlstand zu genießen, den diese verdient haben. Tötet unbedingt mindestens 15 Plünderer der Defias und 15 Ausplünderer der Defias. Das wird ihnen die deutliche Botschaft vermitteln, dass wir Verderbnis hier nicht tolerieren.", completion = "Ihr habt Euren Wert für die Volksmiliz durch die tapferen Taten bewiesen, die Ihr bisher vollbracht habt." }, enUS = { progress = "We have not time to talk, {name}.  The Defias Pillagers are denying the people of Westfall the peace and prosperity they deserve.  Make sure at least 15 Defias Pillagers and 15 Defias Looters have been killed.  That will send a clear message that corruption is not welcome here.", completion = "Your worth to The People's Militia has been validated by your brave acts thus far." } })
apply(14, { "classic", "forever" }, { deDE = { progress = "Es ist jetzt nicht die Zeit für müßiges Geplauder, {name}. Wenn Ihr Euch der Volksmiliz noch immer beweisen wollt, so müsst Ihr die Defias töten, von denen ich Euch zuvor berichtete. Kehrt zu mir zurück, wenn Ihr Eure Pflicht erfüllt habt.", completion = "Als ich Lordaeron, dieses besudelte Land, verließ, fand ich hier, in meiner Heimat, schlimme Zustände vor. Doch es besteht noch Hoffnung für Westfall. Wie Ihr durch Euren Heldenmut im Kampfe bewiesen habt, dient Ihr ganz offensichtlich ehrenvoll unserer Sache. Mit großem Stolz berufe ich Euch in die Volksmiliz ein. Möge das Licht über Euch leuchten." }, enUS = { progress = "{name}, now is no time for idle chatter.  If you still wish to prove yourself to The People's Militia you need to slay the Defias I notified you about earlier.  Return to me when you have completed your duty.", completion = "When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland.  But there is hope for Westfall yet.  As proven by your valor in battle, it is obvious to me that you serve our cause with honor.  It is with great pride that I induct thee into The People's Militia.  May the Light shine upon you." } })
apply(15, { "classic", "forever" }, { deDE = { completion = "Es gefällt mir gar nicht, dass sich so viele Kobolde in unserer Mine herumtreiben. Das bedeutet nichts Gutes. Hier, nehmt dies als Bezahlung und sprecht mich wieder an, sobald Ihr dazu bereit seid. Denn ich möchte, dass Ihr noch einmal in die Minen zurückkehrt." }, enUS = { completion = "I don't like hearing of all these kobolds in our mine.  No good can come of this.  Here, take this as payment, and when you're ready, speak to me again.  I would like you to go back to the mines one more time..." } })
apply(17, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die magenta Funguskappen bekommen, die ich für meine alchimistische Arbeit benötige? Keine Kappen - keine Belohnung!", completion = "Gut gemacht, {name}, Ihr habt Euren Wert abermals bewiesen! Die Pilzkappen werden wahrlich ein interessantes Studienobjekt sein!\n\nUnd nun genießt, wie versprochen, eine Kostprobe meines wirksamen Regenerierungsgebräus aus meinem persönlichen Vorrat...\n\nFalls Ihr ein geübter Alchimist seid, ergeben sich für uns vielleicht noch weitere Geschäfte. Ungeachtet dessen danke ich Euch für Eure Hilfe!" }, enUS = { progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done {name}, you've proven your worth once again!  The caps will be an interesting study, yon verily!\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!" } })
apply(18, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon diese Kopftücher für mich zusammenbekommen?", completion = "Ah, wie ich sehe, seid Ihr zurück und habt Kopftücher dabei. Die Armee von Stormwind weiß Eure Hilfe zu schätzen." }, enUS = { progress = "Have you gathered those bandanas for me yet?", completion = "Back with some bandanas, I see.  The Stormwind Army appreciates your help." } })
apply(19, { "classic", "forever" }, { deDE = { progress = "Die Blackrockorcs setzen uns noch immer stark unter Druck. Aber habt Ihr uns wenigstens von Tharil'zun befreit?", completion = "Tharil'zun war ein bösartiger, verschlagener Orc. Gut gemacht! Ich bin sicher, er war nicht leicht zu besiegen. Hier ist Eure Belohnung, {name}." }, enUS = { progress = "Orc pressure from Blackrock is still tense.  But have you at least rid us of Tharil'zun?", completion = "Tharil'zun was a vicious, crafty orc.  Well done--I'm sure he didn't go down easy.  Here is your reward, {name}." } })
apply(20, { "classic", "forever" }, { deDE = { progress = "Na, habt Ihr Orcs erschlagen, {name}? Dann zeigt es mir.", completion = "Gut, jetzt sind es wesentlich weniger Orcs, um die wir uns sorgen müssen, danke." }, enUS = { progress = "Have you been slaying orcs, {name}?  If so, then show me...", completion = "That makes for a lot fewer orcs to worry about, thanks." } })
apply(21, { "classic", "forever" }, { deDE = { progress = "Ich weiß, das es ein blutiges Geschäft ist, {name}, aber die Sicherheit von Nordhain hängt davon ab. Seid Ihr bereit, mir Bericht zu erstatten?", completion = "Und wieder habt Ihr Euch meinen Respekt und die Dankbarkeit der Armee von Stormwind verdient. Vielleicht gibt es in der Mine noch immer Kobolde, doch ich werde andere schicken, um gegen sie zu kämpfen. Für Euch haben wir andere Aufgaben." }, enUS = { progress = "I know it's bloody work, {name}, but it's vital to the safety of Northshire.  Are you ready to report?", completion = "Once again, you have earned my respect, and the gratitude of the Stormwind Army.  There may yet be kobolds in the mine, but I will marshal others against them.  We have further tasks for you." } })
apply(22, { "classic", "forever" }, { deDE = { progress = "Ich brauche für meine berühmte Fleischpastete nichts weiter als 8 Geiferzahnlebern!", completion = "Die sind genau richtig, {name}! Vielen herzlichen Dank. Heute abend werden Bauer Saldean und ich königlich speisen. Und hier ist auch etwas für Euch, für Eure harte Arbeit. Bei mir muss kein {class} hungern." }, enUS = { progress = "All I need for my famous meat pie are 8 Goretusk Livers!", completion = "These are just perfect, {name}!  Thank you so much.  Farmer Saldean and I are going to feast tonight.  And here is a little something for you, for the hard work.  You didn't think I was going to let a {class} like you go hungry, did you?" } })
apply(23, { "classic", "forever" }, { deDE = { progress = "Ah... {name}... ich habe gerade an Euch gedacht! Wie geht es mit der Jagd voran?", completion = "Ah, die Tatze von Ursangus! Euer Geschick ist beeindruckend, {class}, denn er soll etliche Leute getötet haben. Der Halbmond auf seiner Tatze ist zweifelsohne ein Zeichen, dass er von den Nachtelfen ausgebildet wurde, die in Ashenvale herumschleichen. Ursangus ist... war einer der mächtigsten Bären, die Ihr in dieser Gegend finden konntet. Solch eine Kreatur besiegt zu haben, ist ein Beweis Eurer Willenskraft und Eures Mutes.\n\nEure Vorfahren wären stolz auf Euch!" }, enUS = { progress = "Ah - {name} - I was just thinking about you!  How goes your hunting?", completion = "Ah, the paw of Ursangous!  Your skill is impressive, {class}; he is credited with numerous kills.  The crescent on his paw is no doubt a sign that he was trained by the night elves that skulk about Ashenvale.  Ursangous is... was one of the mightiest bears you'd find in these parts.  To have bested such a creature is a testament to your will and resolve.\n\nYour ancestors would be proud!" } })
apply(24, { "classic", "forever" }, { deDE = { progress = "Seid mir erneut gegrüßt, {name}! Seid Ihr gekommen, um mir einen Beweis Eurer Jagd vorzulegen?", completion = "Ein Sieg für {name} in der Jagd von Ashenvale! Gut gemacht... der Kopf von Schattumbra ist eine passende Trophäe für solch einen beeindruckenden Kampf, keine Frage.\n\nSchattumbras Wildheit war im ganzen Außenposten hier bekannt. Jede Reise nach Westen, insbesondere wenn man zu Fuß versuchte den Zoramstrand zu erreichen, war ob des Tigers von Gefahr überschattet. Dank Euch hat diese Gefahr jetzt ein Ende." }, enUS = { progress = "Greetings once again, {name}!  Have you come to show me proof of your hunt?", completion = "A victory for {name} in the Ashenvale Hunt!  Well done - the head of Shadumbra is a fitting trophy to claim for such an impressive fight, no doubt.\n\nShadumbra's savagery was well known throughout the post here.  Any trip to the west, especially on foot trying to get out to the Zoram Strand, was wrought with danger because of this tiger.  Thanks to you, this danger has abated." } })
apply(25, { "classic", "forever" }, { deDE = { completion = "Ja, ich habe gehört, dass jemand den See auseinander genommen hat wie ein Staubteufel, der durch das Brachland tobt. So wie es klingt, können wir vielleicht außerdem einen Beobachtungsposten da draußen einrichten, um unsere Freunde von der Allianz im Auge zu behalten. Zumindest wenn wir kein Aufsehen erregen...\n\nEs scheint, als hättet Ihr Euch letzten Endes als ziemlich nützlich erwiesen. Die Transporte zwischen hier und dem Steinkrallengebirge sollten jetzt weniger Probleme haben. Nehmt dies - Ihr habt es Euch verdient." }, enUS = { completion = "Yeah, I heard that someone tore up the lake out there like a dust devil through the Barrens.  From the sound of it too, we might be able to set up a possible observation area out there to keep an eye on our Alliance friends.  Well, that is if we can keep it on the down low...\n\nLooks like you ended up being quite useful after all; the transports between here and Stonetalon should have an easier time of it.  Take this - you've earned it." } })
apply(26, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, junger {class}. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen." }, enUS = { completion = "Salutations, young {class}; the time has come for you to know our aquatic form.  It is one that lets you move freely and indefinitely through water.  You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome.  The first will test your ability to work in water under pressure.  The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us." } })
apply(27, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, junger {class}. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen." }, enUS = { completion = "Salutations, young {class}; the time has come for you to know our aquatic form.  It is one that lets you move freely and indefinitely through water.  You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome.  The first will test your ability to work in water under pressure.  The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us." } })
apply(28, { "classic", "forever" }, { deDE = { progress = "Um die Prüfung des Sees abzuschließen, müsst Ihr das Schreinschmuckstück im Umkreis des Schreines benutzen. Solange Ihr das nicht getan habt, bleibt Eure Prüfung unvollständig und Ihr riskiert einen Fehlschlag.", completion = "Na so was, es sieht so aus, als hätte erneut ein {class} die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel." }, enUS = { progress = "To complete the Trial of the Lake, you must use the Shrine Bauble within the boundaries of this shrine.  Until you do so, your trial remains unfinished and it is at risk of failure.", completion = "Well now, it looks like yet another {class} has successfully completed the Trial of the Lake!  Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri.  It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine.  Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such.  By using the bauble here, it serves as a nod to the importance of this place within the Circle." } })
apply(29, { "classic", "forever" }, { deDE = { progress = "Um die Prüfung des Sees abzuschließen, müsst Ihr das Schreinschmuckstück im Umkreis des Schreines benutzen. Solange Ihr das nicht getan habt, bleibt Eure Prüfung unvollständig und Ihr riskiert einen Fehlschlag.", completion = "Na so was, es sieht so aus, als hätte erneut ein {class} die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel." }, enUS = { progress = "To complete the Trial of the Lake, you must use the Shrine Bauble within the boundaries of this shrine.  Until you do so, your trial remains unfinished and it is at risk of failure.", completion = "Well now, it looks like yet another {class} has successfully completed the Trial of the Lake!  Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri.  It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine.  Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such.  By using the bauble here, it serves as a nod to the importance of this place within the Circle." } })
apply(30, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, {name}? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, {name}... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt." }, enUS = { progress = "Have you formed your pendant for me to inspect, {name}?  If you need help in locating the parts, try asking the local populace for information.  Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, {name} - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form." } })
apply(31, { "classic", "forever" }, { deDE = { progress = "Eure Rückkehr nach Thunder Bluff kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, {name}. Eure Vorfahren wären erfreut über Euren Fortschritt! Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen." }, enUS = { progress = "Your return to Thunder Bluff is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.\n\nDo you have the Pendant of the Sea Lion?", completion = "Very impressive, {name}.  Your ancestors would be pleased with your progress!  You're ready to learn your aquatic form, and it is my pleasure to teach it to you.\n\nAlso, in recognition of your achievement during the two trials, I give you this item.  I hope you'll find it to be a welcome addition to your gear as a protector of nature and a keeper of the balance." } })
apply(32, { "classic", "forever" }, { deDE = { progress = "Es tut mir Leid, ich kenne Euch nicht... aber so wie es aussieht, habt Ihr zumindest schon von mir gehört. Nun, wie kann ich Euch helfen? Habt Ihr etwas für mich?", completion = "Dieser Bericht... Ich habe mich schon zuvor mit diesen Bestien beschäftigt. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, {name}: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen." }, enUS = { progress = "I'm sorry, I don't know you... but from the look of things you have at least heard something of me.  Now, what can I help you with?  Do you have something for me?", completion = "This report... I've dealt with these beasts before.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, {name}: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before." } })
apply(33, { "classic", "forever" }, { deDE = { progress = "He, {name}, Ich kriege langsam Hunger. Habt Ihr das zähe Wolfsfleisch bekommen?", completion = "Ihr wart aber fleißig! Ich kann es kaum erwarten, dieses Wolfsfleisch aufs Feuer zu bringen.\n\nIch habe hier ein paar Sachen, die Euch vielleicht gefallen könnten - greift zu!" }, enUS = { progress = "Hey {name}.  I'm getting hungry...did you get that tough wolf meat?", completion = "You've been busy!  I can't wait to cook up that wolf meat...\n\nI have some things here you might want - take your pick!" } })
apply(34, { "classic", "forever" }, { deDE = { progress = "Treibt Stopfwanst noch immer sein Unwesen, oder ist es Euch gelungen, Seenhain ein für alle Mal von dieser Plage zu befreien?", completion = "Endlich hat die Bedrohung ein Ende! Ich danke Euch, {name}, Ihr habt mir einen großen Dienst erwiesen. Dieses Jahr wird mein Garten herrlich blühen!" }, enUS = { progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, {name}, you have done me a great service.  The garden shall be in full bloom this season!" } })
apply(35, { "classic", "forever" }, { deDE = { completion = "Ja, es haben sich Murlocs in und an den Flüssen und Bächen des östlichen Elwynn niedergelassen. Wir wissen nicht, warum sie hergekommen sind, aber sie sind aggressiv und zumindest halbintelligent." }, enUS = { completion = "Yes, murlocs have settled in and around the streams of eastern Elwynn.  We don't know why they are here, but they are aggressive and at least semi-intelligent." } })
apply(36, { "classic", "forever" }, { deDE = { progress = "Ich werde die Verna Furlbrow sehr vermissen! Ich nehme nicht an, dass Ihr ihr auf dem Weg hierher begegnet seid?", completion = "Die Verna ist immer so ein liebes Mädchen gewesen! Wir werden sie hier in Westfall vermissen, aber ganz ehrlich und nur unter uns, sie ist ja eigentlich ein Stadtkind und deswegen wird sie sich in Stormwind pudelwohl fühlen. Aber genug getratscht! Jetzt können wir Westfall-Eintopf kochen!" }, enUS = { progress = "I'm going to miss that Verna Furlbrow so much.  I don't suppose you happened to see her on your way here?", completion = "That Verna was always such a sweet lass.  We'll miss her here in Westfall but between you and me, she's a city girl at heart and Stormwind will suit her just fine.  But enough gossip!  Now we can make Westfall Stew!" } })
apply(37, { "classic", "forever" }, { deDE = { completion = "Vom Leichnam selbst ist nicht mehr viel zu erkennen. Doch in der Nähe findet Ihr ein Medallion, in das die Worte \"Malakai Stone, Soldat\" eingeprägt sind." }, enUS = { completion = "Although much has been stripped from the corpse, strewn nearby is a medallion with the words: \"Footman Malakai Stone\" etched upon it." } })
apply(38, { "classic", "forever" }, { deDE = { progress = "Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch\n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", completion = "Das Okra wird die Brühe schön eindicken. Und jetzt geben wir nur noch das sehnige Geierfleisch, ein paar Murlocaugen und diese leckeren Geiferzahnschnauzen dazu. Und fertig! Ich möchte, dass Ihr für all Eure Hilfe den ersten Schwung Westfall-Eintopf bekommt, {name}. Hier, nehmt!" }, enUS = { progress = "Come back with the following ingredients: \n\n 3 Stringy Vulture Meat\n 3 Goretusk Snouts\n 3 Murloc Eyes\n 3 Okra", completion = "That Okra will thicken up this broth nicely!  Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts.  And we're done!  For all your help, {name}, I want you to take today's first batch of Westfall Stew!" } })
apply(39, { "classic", "forever" }, { deDE = { completion = "Hmm... das sind beunruhigende Neuigkeiten. Unsere Reihen sind ohnehin schon ausgedünnt, und dass wir jetzt auch noch Rolf und Malakai verloren haben, macht die Lage noch schlimmer.\n\nWenn sich die Dinge nicht bald ändern, dann wird in ein paar Tagen sogar Goldhain umkämpft sein." }, enUS = { completion = "Hmm, this news is troubling.  Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.\n\nIf things don't improve, there will be fighting in Goldshire by the week's end!" } })
apply(40, { "classic", "forever" }, { deDE = { completion = "Ja, ich habe mit Remy darüber gesprochen. Er ist ein guter Händler und ich respektiere ihn, aber alle Berichte von Murlocs im Osten waren bisher bestenfalls bruchstückhaft.\n\nIch nehme Eure Sorgen zur Kenntnis, aber solange ich nicht einen zuverlässigen Bericht aus berufener militärischer Quelle erhalte, der bestätigt, dass die Murlocs tatsächlich eine Bedrohung darstellen, können wir es uns nicht leisten, weitere Soldaten nach Osten zu schicken." }, enUS = { completion = "Yes, I spoke with Remy.  I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.\n\nYour concerns are noted, but unless I receive a military report of a murloc threat, we can't afford to send more troops east." } })
apply(45, { "classic", "forever" }, { deDE = { completion = "Um den Hals trägt der Leichnam ein Medaillon aus Metall, auf dem die Worte \"Rolf Hartford, Soldat\" stehen." }, enUS = { completion = "You find around the neck of the corpse a metal medallion inscribed with the words \"Footman Rolf Hartford.\"" } })
apply(46, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd, {name}?", completion = "Habt Ihr die Flossen? Ausgezeichnet! Marshal Dughan ist besorgt wegen der Murlocbedrohung in Ost-Elwynn und ich würde ihm gern berichten können, dass wir die Lage langsam unter Kontrolle bekommen.\n\nMit Euren Taten habt Ihr uns dabei geholfen." }, enUS = { progress = "How goes the hunting, {name}?", completion = "You have the fins?  Great!  Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I'd like to tell him that it's becoming under control.\n\nYour actions have helped realize that." } })
apply(47, { "classic", "forever" }, { deDE = { progress = "Psst! Habt Ihr den Goldstaub für mich... für mich?", completion = "Danke für den Goldstaub, {name}. Hier habt Ihr Euer Geld und hier habt Ihr noch eine kleine... Zugabe von Freunden von mir. Das könnte Euch vielleicht noch nützlich werden... nützlich werden." }, enUS = { progress = "Psst!  You have that Gold Dust for me...for me?", completion = "Thanks for the dust, {name}.  Here's your cash, and...here is a token from associates of mine.  You might find it useful...useful." } })
apply(48, { "classic", "forever" }, { deDE = { progress = "Hicks und Hurra, Wollt Ihr's nochma'?\n\nWeit im Süden, wo die Lianen sich ranken,\nLiegt versteckt ein Brunnen, in dem sie fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", completion = "Hicks und Hurra!" }, enUS = { progress = "Hiccup! Ho ho!  You want an encore?\n\nIn the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", completion = "Hiccup! Ho Ho!" } })
apply(49, { "classic", "forever" }, { deDE = { progress = "Nochma'? Na klar!\n\nLang schon vermiss ich die Lieb meines Lebens,\nGoldbraun und samtig, doch noch wart ich vergebens.\nBringt mir, dann vergeht jeder Zorn,\nJe einen Sack Gerste, Roggen und Korn.", completion = "Hicks und Hurra!" }, enUS = { progress = "Encore? Well, sure!\n\nAmber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", completion = "Hiccup! Ho ho!" } })
apply(50, { "classic", "forever" }, { deDE = { progress = "Wollt Ihr's noch mal hören? Dann lasst Euch nicht stören!\n\nDie Maische anrühren, das ist mein Wille,\nDoch fehlt mir dann auch noch eine Destille\nFür diese brauch ich ein starkes Metall\nBringt mir Echtsilber, das ist gut in dem Fall!", completion = "Hicks und Hurra!" }, enUS = { progress = "An encore for you?  Well sure friend!\n\nI'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", completion = "Hiccup! Ho ho!" } })
apply(51, { "classic", "forever" }, { deDE = { progress = "Soll ich's noch mal sagen? Ihr müsst mich nur fragen!\n\nNoch ist er nicht fertig, doch schon fertig gebrannt.\nJetzt wird als Nächstes der Meiler bemannt, \nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", completion = "Hicks und Hurra!" }, enUS = { progress = "An encore?  Why for you, anything!\n\nNot yet filtered but freshly distilled\nLike unseeded land waiting there tilled. \nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", completion = "Hiccup! Ho ho!" } })
apply(52, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Wölfe und Bären schon getötet, von denen ich sprach?", completion = "Vielen Dank für Eure Hilfe, {name}. Im Wald muss es irgendetwas geben, das die Tiere so angriffslustig macht.\n\nWas auch immer es sein mag, ich hoffe, es bleibt dort!" }, enUS = { progress = "Have you killed those wolves and bears?", completion = "Thanks a lot for the help, {name}.  Something in the forest must be making these animals so bold.\n\nWhatever it is, I hope it stays there." } })
apply(53, { "classic", "forever" }, { deDE = { progress = "Soll ich's noch mal singen? Ihr müsst mich nicht zwingen!\n\nDas Getränk, das ich braue, das reine und klare,\nWird goldbraun und samtig im Laufe der Jahre.\nDoch ehe er fertig, der Whisky, der weiche,\nBraucht's noch ein Fass aus verkohlter Eiche.", completion = "Im Fasse gealtert, gefiltert durch Kohle,\nRinnt er durch die Kehle zu jedermanns Wohle.\nSo lasset uns trinken und prosten mit dem Gebräu.\nAuf Euch und auf mich, Grimbooze Donnerbräu!" }, enUS = { progress = "Sure, I'll sing it again for you, friend!\n\nMellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", completion = "Aged in the barrel, filtered through coal\nIt passes your lips and right through your soul.\nSo lets us drink now, a toast to you\nAnd me while we're at it, Grimbooze Thunderbrew!" } })
apply(54, { "classic", "forever" }, { deDE = { progress = "Ihr bringt Nachricht von McBride? Im Vergleich zum Wald von Elwynn ist Nordhain das reinste Paradies. Wir wollen doch mal sehen, was Marshal McBride so zu berichten hat...\n\nGebt mir doch bitte seine Papiere.", completion = "Oha, hier steht, dass Ihr in den Rang des kommissarisch ernannten Deputys der Marshals von Stormwind erhoben worden seid. Herzlichen Glückwunsch.\n\nUnd viel Erfolg bei der Arbeit - Elwynn sicher zu machen ist kein Spaziergang, zumal der größte Teil der Armee sonstwo zugange ist und sonstwas für irgendwelche Adligen macht!\n\nEs ist schon schwer, in diesen dunklen Zeiten den Überblick über die Politik zu behalten..." }, enUS = { progress = "You have word from McBride?  Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.\n\nHere, let me have his papers...", completion = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals.  Congratulations.\n\nAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!\n\nIt's hard to keep track of politics in these dark days..." } })
apply(56, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe, seid Ihr zurück, {name}. Wenn Ihr Euch für die Nachtwache als nützlich erweisen wollt, dann kehrt zu mir zurück, sobald Ihr 8 Skelettkrieger und 6 Skelettmagier getötet habt.", completion = "Ausgezeichnet, {name}. Für Eure Dienste an ganz Dunkelhain sollt Ihr gut belohnt werden." }, enUS = { progress = "I see you are back, {name}.  If you wish to prove yourself to be of service to The Night Watch, return to me once you have slain 8 Skeletal Warriors and 6 Skeletal Mages.", completion = "Splendid, {name}.  For your service to the people of Darkshire you shall be rewarded." } })
apply(57, { "classic", "forever" }, { deDE = { completion = "Die Bewohner von Dunkelhain sind Euch zu Dank verpflichtet, {name}. Ihr habt bewiesen, dass Ihr der Nachtwache ein wertvoller Verbündeter seid." }, enUS = { completion = "The people of Darkshire thank you, {name}.  You have proven yourself to be a great ally of The Night Watch." } })
apply(58, { "classic", "forever" }, { deDE = { completion = "Im Namen der Bewohner von Dunkelhain und als Anführerin der Nachtwache danke ich Euch, {name}, für Euren Mut und Eure Hingabe. Möge das Licht über all Euren Wegen leuchten." }, enUS = { completion = "On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, {name}, for your bravery and dedication.  May the Light shine upon your ways." } })
apply(59, { "classic", "forever" }, { deDE = { progress = "Ich bin von der Armee von Stormwind beauftragt, ihre Soldaten mit Rüstung aus Tuch und aus Leder auszustatten.\n\nWenn Ihr einen Gutschein für mich habt, dann stelle ich gern etwas für Euch her.", completion = "Ja, einen solchen Gutschein meinte ich. Danke! Bitte sucht Euch das Stück aus, das Ihr möchtet.\n\nIch wünsche Euch viel Glück auf Eurem Weg als {class}. Und möge diese Rüstung Euch gute Dienste leisten." }, enUS = { progress = "I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.\n\nIf you have a marker for me, then I'd be happy to make you something.", completion = "Ah, thank you for the marker.  Please feel free to pick your choice of armor.\n\nLuck to you, brave {class}.  And may this armor serve you well." } })
apply(61, { "classic", "forever" }, { deDE = { progress = "Ah, eine Lieferung von meinem Bruder? Ausgezeichnet! Heute ist mir das Glück wirklich gewogen!", completion = "Hier habt Ihr Eure Bezahlung. Und wenn Ihr schon einmal hier seid, schaut Euch ruhig um! Ich bin sicher, dass wir den einen oder anderen Trank oder sonst irgendetwas haben, dass Euch von Nutzen wäre." }, enUS = { progress = "Oh, a shipment from my brother?  Splendid!  Fortune truly shines on me today!", completion = "Here is your payment ... and while you're here, take a look around!  I'm sure we have a potion or other trinket you'd find useful." } })
apply(62, { "classic", "forever" }, { deDE = { progress = "Was gibt es zu berichten, {name}? Seid Ihr in der Tiefenschachtmine gewesen?", completion = "Das sind allerdings schlechte Nachrichten. Was kommt als Nächstes, Drachen?!? Wir werden wohl unsere Patrouillen rund um die Mine verstärken müssen. Habt Dank für Eure Bemühungen, {name}. Und wartet einen Moment... Ich habe vielleicht noch eine andere Aufgabe für Euch." }, enUS = { progress = "What do you have to report, {name}?  Have you been to the Fargodeep Mine?", completion = "This is bad news.  What's next, dragons?!?  We'll have to increase our patrols near that mine.  Thanks for your efforts, {name}.  And hold a moment... I might have another task for you." } })
apply(63, { "classic", "forever" }, { deDE = { progress = "Die Kohlenpfanne wirft immer noch das Licht der Umgebung zurück und die Flammen flackern leise, als Ihr näher herantretet.\n\nDie in diesen Bergen vorherrschende Verderbnis scheint sich hier noch nicht ausgebreitet zu haben und abgesehen von den fehlenden Komponenten scheint die Kohlenpfanne bereit dafür zu sein, dass jemand das Ritual zur Beschwörung einer gesäuberten Wassermanifestation durchführt.", completion = "Ihr legt die Armschienen des Elementars auf die Kohlenpfanne, dann gießt Ihr die verbleibenden Tropfen von Brines Trank in die Flammen. Die Flüssigkeit knistert, als sie mit den Flammen in Berührung kommt, und Ihr beginnt, die einfachen Worte zu rezitieren, die Islen Euch gelehrt hat..." }, enUS = { progress = "The brazier still reflects the ambient light from the area, and the flame shifts slightly as you move closer.\n\nThe corruption along the hills seems to have kept its distance, and besides the missing components, the brazier looks prepared for the ritual to summon a cleansed manifestation of water.", completion = "You place the bracers atop the brazier and then pour the remaining drops of Brine's potion into the flame. The drops crackle as they hit the flame and you begin to incant the simple words Islen taught you...." } })
apply(64, { "classic", "forever" }, { deDE = { progress = "Ich nehm nicht an, dass Ihr meine Uhr gekriegt habt, oder?", completion = "Meine Uhr! Oh, danke, danke vielmals, werter Herr! \n\nWir sind nur arme Bauern und wir haben unser Land verloren, aber nehmt doch bitte dies als Zeichen unseres Dankes." }, enUS = { progress = "Don't suppose you were able to get my watch?", completion = "My watch!  Thank you so much, kind sir! \n\nWe are but poor farmers and we have lost our land but please accept this reward as a token of our appreciation." } })
apply(65, { "classic", "forever" }, { deDE = { completion = "So, Stoutmantle hat Euch geschickt, hm? Na ja, dem schulde ich noch was." }, enUS = { completion = "So, Stoutmantle sent you?  Well, I owe him." } })
apply(66, { "classic", "forever" }, { deDE = { completion = "Madame Eva hat Euch also geschickt..." }, enUS = { completion = "Ah so Madame Eva sent you. . . ." } })
apply(67, { "classic", "forever" }, { deDE = { completion = "Quietschend öffnet sich die alte Schließkiste..." }, enUS = { completion = "The old footlocker creaks open. . . ." } })
apply(68, { "classic", "forever" }, { deDE = { progress = "Ah, ich erinnere mich an Euch. Ihr hattet Euch doch nach diesem Stalvan erkundigt. Habt Ihr gefunden, wonach Ihr gesucht hattet?", completion = "Interessant. Also hat sich der Bursche doch einige Zeit lang in Moonbrook aufgehalten. Es ist etwas seltsam, dass der Brief nie zugestellt wurde. Nun, wie dem auch sei, ich werde das Verzeichnis aktualisieren." }, enUS = { progress = "Ah, I remember you.  You're the one who was asking about that Stalvan fellow.  Did you ever find what you were looking for?", completion = "Interesting.  So the chap did spend some time in Moonbrook after all.  It is rather odd the letter never got delivered.  Nonetheless, I shall update the registry." } })
apply(69, { "classic", "forever" }, { deDE = { completion = "Stalvan? Kommt mir irgendwie bekannt vor..." }, enUS = { completion = "Stalvan?  Sure sounds familiar." } })
apply(70, { "classic", "forever" }, { deDE = { progress = "Was habt'n Ihr da, hm? Lasst mich das mal sehen...", completion = "Ihr habt vielleicht Nerven, dass Ihr das hierher bringt." }, enUS = { progress = "What have ya got there?  Let me take a look at that. . .", completion = "You've got some nerve bringing this here." } })
apply(71, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr herausgefunden, was aus Rolf und Malakai geworden ist?", completion = "Damit bestätigt Ihr meine Befürchtungen, {name}. Die Murlocs sind eine Bedrohung, die wir nicht länger ignorieren können." }, enUS = { progress = "Hello, {name}.  Have you discovered the fates of Rolf and Malakai?", completion = "You have confirmed my fears, {name}.  The murlocs are a threat we cannot ignore." } })
apply(72, { "classic", "forever" }, { deDE = { completion = "Langsam schiebt Ihr den Deckel von der Kiste..." }, enUS = { completion = "You slowly slide the lid of the crate off. . . ." } })
apply(74, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da? Ich kann es nicht sehen. Ich habe sehr schwache Augen. Gebt es mir bitte in die Hand.", completion = "Ich kann kaum lesen, was da steht, aber die Handschrift erinnert mich an etwas, das ich mal gesehen habe, bevor meine Sehkraft so nachgelassen hat." }, enUS = { progress = "What have you got there?  I cannot see.  My eyesight is very bad.  Put it in my hands.", completion = "I can barely make out those letters.  But that writing style reminds me of something I once saw before my vision became so poor." } })
apply(75, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Seite gefunden, von der ich sprach, {name}?", completion = "Da ist sie ja!" }, enUS = { progress = "Did you find that page I mentioned, {name}?", completion = "You found it!" } })
apply(76, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Was habt Ihr zu berichten? Habt Ihr die Jaspismine ausgekundschaftet?", completion = "Kobolde in der Jaspismine, sagt Ihr? Verflucht noch eins! Die Lage wird von Minute zu Minute schlimmer!\n\nVielen Dank für Euren Bericht, {name}. Aber ich wünschte mir, Ihr hättet bessere Nachrichten gebracht." }, enUS = { progress = "Hail, {name}.  What do you have to report? Have you scouted the Jasperlode Mine?", completion = "Kobolds at the Jasperlode Mine, you say?  Curses!  The situation is worsening by the minute!\n\nThank you for the report, {name}.  But I wish that the news you brought was good news." } })
apply(77, { "classic", "forever" }, { deDE = { progress = "Ich nehme an, Eure Ankunft in unserem Lager dient der Lieferung der Wellenflaschen, die wichtiger Bestandteil der anstehenden Aufgabe sind, nicht wahr?", completion = "Das habt Ihr hervorragend gemacht, {name}! Ich bin froh, dass Ihr genug Voraussicht gezeigt und das Bouquet der Welle nicht verletzt habt. Es gibt nichts Schlimmeres, als wenn das Bouquet der Welle unnötig erschüttert wird.\n\nEs dauert einen Moment, die Magie um diese wertvolle Fracht zu wirken. Eigentlich ist ja gar keine Magie im Spiel; ich habe einfach nur einige leere Verpackungen für Hinterland-Honigwelle. Unser kleiner Trick wird diese Flaschen in einen alkoholischen Schatz von hohem Alter verwandeln.\n\nNun denn - auf dass es großartiger Schnaps werde!" }, enUS = { progress = "I trust that your arrival here at our camp is to deliver the bottles of ripple that are integral to the task at hand, yes?", completion = "Finely executed, {name}.  I am glad you had enough foresight not to bruise the delicacy of the ripple.  There is nothing worse than the bouquet of ripple that has been jostled about needlessly.\n\nIt will take a moment for the magic to be wrought over this precious cargo.  Actually, no magic is involved; I merely have some empty packaging for Hinterlands Honey Ripple.  Our chicanery shall turn these bottles into an alcoholic treasure of the ages.\n\nOnward - for great booze!" } })
apply(78, { "classic", "forever" }, { deDE = { progress = "Marshal Haggard hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt? \n\nAch ja, der gute alte Haggard. Der arme Kerl wird über kurz oder lang stockblind werden. Aber egal, zeigt mir mal, was Ihr da habt.", completion = "Beim Licht! Aber sicher erkenne ich die Handschrift." }, enUS = { progress = "Marshal Haggard sent you?  Why didn't you say so? \n\nAh, good ol' Haggard.  Poor chap is going to be completely blind before long.  Anyway, let me see what you've got there.", completion = "By the Light!  You bet I recognize that handwriting." } })
apply(79, { "classic", "forever" }, { deDE = { progress = "Nun, {class}, ich hoffe, das, was Ihr mir da bringt, taugt auch etwas. Zeigt es mir und erzählt mir, was es damit auf sich hat. Aber beeilt Euch ein bisschen, beim Licht! Denn die Verteidigung von Dunkelhain ist mein wichtigstes Anliegen; ich habe einfach nicht die Zeit, mich bei meinen Ermittlungen in Sackgassen zu stürzen!", completion = "Ihr habt Euch ja richtiggehend als Detektiv betätigt, und das als {class}. Respekt!" }, enUS = { progress = "This better be good, {class}.  Let me see what you have and tell me your tale.  But by the Light, be quick about it.  Darkshire's defense is my number one priority.  I have not the time to squander on dead-end leads.", completion = "My, you have proved yourself to be quite a detective, {class}." } })
apply(80, { "classic", "forever" }, { deDE = { progress = "Ihr seid ja schon wieder da, {name}! Was gibt es diesmal?", completion = "Aber ja! Die Handschrift auf dieser Seite ist tatsächlich dieselbe wie die der Unterschriften im Verzeichnis." }, enUS = { progress = "Back again, {name}?  What do you have this time?", completion = "Why yes!  The writing on this page does in fact match that of the registry signatures." } })
apply(81, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr nicht hier seid, um etwas zu kaufen, und auch nicht, um etwas abzuliefern, dann verschwendet Ihr meine Zeit! Es wäre für Euch besser, Ihr hättet diese Welle!", completion = "Tja, dann schauen wir mal, was in diesem Fass ist!\n\nJa, ja, sieht aus als wäre alles da. Hier ist Euer Unkostenbeitrag für das Paket, Ihr habt gute Arbeit geleistet. Ich werde das Fünffache der Unkosten herausholen, wenn ich das Zeug an die Taverne verkaufe! Har, har!\n\nDiese zusätzlichen Flaschen Hinterland-Honigwelle werde ich für eine besondere Gelegenheit aufbewahren. Ich werde am besten etwas davon mit Champagner vermischt trinken. Ich nenne das... Champelle." }, enUS = { progress = "If you're not here to buy anything, and you're not here to deliver anything, then you're wasting my time!  You better have that ripple!", completion = "Well, let's see what's in this barrel!\n\nYes, yes, it looks as though it is all here.  Here's your fee for the package, good job on that.  I stand to make five times that fee when I sell it to the tavern!  Har har!\n\nThese extra bottles of Hinterlands Honey Ripple are going to be set for a special occasion.  I think I'll drink some with champagne.  I'll call it... champipple." } })
apply(82, { "classic", "forever" }, { deDE = { progress = "Ihr seid Unterfeldmesser {name}, nicht wahr? Macht schnell, denn wir befinden uns hier in einer schrecklichen Lage! Habt Ihr die Insektenteile, wie Fizzledowser gesagt hat?!", completion = "Gute Arbeit... ich werde jetzt mit der Analyse dieser Dinger beginnen! Eines kann ich Euch aber direkt sagen... es handelt sich hier um keine mir bekannte Insektenform. Es scheint fast so, als würden diese Käfer von einer fremden Macht kontrolliert oder so was.\n\nIhr müsst auf der Stelle mit Fizzledowser sprechen; anscheinend gibt es einen Notfall, bei dem er Eure Hilfe benötigt. Ich bin mir nicht sicher, aber ich glaube, es geht um weitere Käfer in der Tanariswüste!" }, enUS = { progress = "You're Junior Surveyor {name}, yes?  Quickly now, there is a dire situation at hand!  Do you have the insect parts that Fizzledowser said you would?!", completion = "Good work - I'll start my analysis on these now!  I can tell you right from the start though... these are nothing like any insect form I have ever seen.  It's almost as if these bugs are being controlled by an outside force or something.\n\nYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double!  I'm not sure, but I think it involves more of the bugs in the Tanaris desert!" } })
apply(83, { "classic", "forever" }, { deDE = { progress = "Ich habe fast kein Leinen mehr, {name}. Bringt Ihr mir welches?", completion = "Ah ja, das sind schöne Kopftücher, obwohl der Stoff ein wenig rau ist...\n\nHier, bitte schön!" }, enUS = { progress = "I'm running low on linen, {name}.  Do you have any for me?", completion = "Ah, these are nice bandanas, if a little rough...\n\nHere you are!" } })
apply(84, { "classic", "forever" }, { deDE = { progress = "Aaah... Ich bin am Verhungern! Habt Ihr die Pastete für mich, {name}?", completion = "Mmmm, lecker! Diese Pastete ist perfekt!\n\nIch glaube, langsam kommt mein Gedächtnis wieder..." }, enUS = { progress = "Ugh... I'm starving!  Do you have that pie for me, {name}?", completion = "Mm, yum!  This pie is the best!\n\nI think my memory is coming back to me..." } })
apply(85, { "classic", "forever" }, { deDE = { completion = "Ihr habt was verloren? Also ich hab keine Kette genommen, denn ich bin kein Dieb!\n\nIch weiß vielleicht, wer's war, aber... <grins>... ich hab einfach zu viel Hunger, um drauf zu kommen." }, enUS = { completion = "You lost a what?  Well I didn't take no necklace, because I ain't no thief!\n\nI might know who did but...<grin>...I'm too hungry to remember." } })
apply(86, { "classic", "forever" }, { deDE = { progress = "Ich halte es nicht für richtig, den frechen Jungen, der meine Kette überhaupt erst gestohlen hat, dafür auch noch zu füttern, aber wenn es sein muss, damit ich mein Eigentum wiederbekomme, dann soll es eben so sein.\n\nHabt Ihr das Eberfleisch?", completion = "Das Fleisch von wilden Ebern ist zwar zäh, aber wenn man es lange genug köcheln lässt, dann wird eine ganz vorzügliche Pastete daraus!" }, enUS = { progress = "I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it!\n\nDo you have that boar meat?", completion = "Though this wild boar meat is tough, simmer it enough and it sure does make for some tasty pie!" } })
apply(87, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr meine Halskette gefunden?", completion = "Oh, Ihr habt sie tatsächlich gefunden! Danke, danke, mein Lieber!\n\nHier, nehmt dies. Es hat meinem Mann gehört und er sagte immer, dass es Glück brächte. Wenn er es doch nur auf seinem letzten Feldzug nicht vergessen hätte! *schnief*" }, enUS = { progress = "Hello, {name}.  Have you found my necklace?", completion = "Oh, you found it!  Thank you, thank you dear!\n\nHere, take this.  It was my husband's and he always said it was lucky.  If only he didn't forget it on his last campaign! *sniff*" } })
apply(88, { "classic", "forever" }, { deDE = { progress = "Habt Ihr sie schon gesehen? Habt Ihr sie erwischt?", completion = "Welch ein Glück! Dieses Schwein war schon so groß, dass es bestimmt bald unsere gesamte Ernte gefressen hätte! Ich danke Euch, {name}.\n\nNun, könnt Ihr mit einem dieser Dinge hier etwas anfangen?" }, enUS = { progress = "Did you see her yet?  Did you get her?", completion = "Thank goodness!  That pig was getting so big she'd have eaten our whole crop!  Thank you, {name}.\n\nNow, do either of these suit you?" } })
apply(89, { "classic", "forever" }, { deDE = { progress = "Diese Brücke wird sich nicht selber bauen! Also wo sind diese Eisenspitzen und Eisennieten?", completion = "Gute Arbeit, {name}. Dieses Material wird den Brückenbau ganz enorm beschleunigen. Die kleine Schönheit hier wird im Handumdrehen repariert sein." }, enUS = { progress = "This bridge isn't going to build itself!  Now where are those iron pikes and iron rivets?", completion = "Great work, {name}.  These supplies will help the bridge effort immensely.  We'll get this beauty shored up in no time." } })
apply(90, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die 10 mageren Wolfflanken schon zusammen? Und was ist mit den Kräutern von Felicia aus Stormwind?", completion = "Gut gemacht, {name}! Ich wünsche Euch guten Appetit bei dieser echten Spezialität, dem gewürzten Wolfskebab!" }, enUS = { progress = "Were you able to find 10 Lean Wolf Flanks yet?  How about the herbs from Felicia in Stormwind?", completion = "Very nice work, {name}!  Enjoy the delicacy known as Seasoned Wolf Kabob!" } })
apply(91, { "classic", "forever" }, { deDE = { progress = "Gebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", completion = "Das Gericht von Seenhain weiß Euren Einsatz für die Gerechtigkeit zu schätzen, {name}. Indem Ihr die Gesetze des Königreichs durchgesetzt habt, habt Ihr auch der Gerechtigkeit in diesem Land einen Sieg verschafft." }, enUS = { progress = "Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.", completion = "The Court of Lakeshire recognizes your commitment to justice, {name}.  By enforcing the laws of the Kingdom you have helped uphold the justice of the land." } })
apply(92, { "classic", "forever" }, { deDE = { progress = "Ich brauche immer noch 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", completion = "Gut gemacht, {name}. Und so schöne Exemplare noch dazu! Dafür bekommt Ihr hier auch die köstliche Spezialität, die als Rotkammgulasch bekannt ist!" }, enUS = { progress = "I still need five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", completion = "Well done, {name}. Such fine specimens too! And here is your delicious delicacy known as Redridge Goulash!" } })
apply(93, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Habt Ihr die klebrigen Spinnenbeine schon zusammen?", completion = "Ah ja, da habt Ihr ja ein paar nette Beinchen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt." }, enUS = { progress = "Hail, {name}.  Did you get those Gooey Spider Legs yet?", completion = "Ah yes, a nice clutch of legs you have there!  Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good." } })
apply(94, { "classic", "forever" }, { deDE = { progress = "Die Löwenstatue steht schon seit Jahrzehnten hier und bewacht einsam und allein den berüchtigten Turm von Ilgalar.\n\nAm Sockel der Statue befindet sich eine Vertiefung, wo ein Edelstein oder eine Glyphe eingesetzt werden könnte...", completion = "Ihr legt die Glyphe von Azora auf den Stein. Auf magische Weise verbindet die Glyphe sich mit der Statue - und als dies geschehen ist, hört Ihr plötzlich Theocritus' Stimme aus ihr ertönen:\n\nSeid Euch meiner Dankbarkeit gewiss, {name}, mein junger Freund. Ihr habt jetzt die Möglichkeit, durch diese Glyphe mit mir zu sprechen - es ist gut möglich, dass ich in Zukunft weitere Aufgaben für Euch habe. Aber erst muss ich die Gedanken meines Widersachers studieren." }, enUS = { progress = "This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.\n\nThere is a depression at the base of the statue, where a gem or glyph might be set...", completion = "You place the Glyph of Azora on the stone.  It adheres itself ... and you hear from it Theocritus' disembodied voice:\n\nYou have my gratitude, young {name}.  You may now speak with me through this Glyph, and I might have future tasks for you ... after I have probed the thoughts of my rival." } })
apply(95, { "classic", "forever" }, { deDE = { completion = "Ihr seht einen Haufen eilig aufgeschütteter Erde: Es scheint, als habe jemand etwas verstecken wollen und nicht viel Zeit gehabt, um dies zu tun." }, enUS = { completion = "A mound of dirt is here, hastily piled up as if someone had need of hiding something...without much time to do it." } })
apply(96, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurückgekehrt. Ausgezeichnet!\n\nWie war Eure Reise nach Silberwald? Wart Ihr lange unterwegs?\n\nEs ist schwer für mich, festzustellen, ob Ihr Erfolg hattet oder nicht, denn ein so großer Teil des Landes ist bereits verderbt. Der Gestank der Verderbnis legt sich über alles Gute, das Ihr dort getan haben mögt. Doch die kleinen Erfolge sind manchmal genauso wichtig wie die großen. Die Läuterung des Wassers war höchst bedeutsam für Euch, nein, für alle Schamanen.", completion = "Dies ist der Beweis, um den ich Euch gebeten hatte. Ihr habt Eure Sache gut gemacht, {name}.\n\nIch freue mich, dass ich die Erste bin, die Euch gratuliert, und dass ich Euch dies geben kann - Euer Wassertotem.\n\nVerwendet es klug - und viel Glück.\n\nBis zu Eurer nächsten Prüfung wird es noch eine Weile dauern, also lernt Eure Lektionen sorgfältig bis dahin. Reines Wasser kann nicht nur Verletzten das Leben zurückgeben, sondern hat auch andere vielfältige Wirkungen. Ich schlage vor, Ihr sucht einen Schamanenlehrer auf, wenn Ihr die Zeit dafür habt. Dort könnt Ihr vielleicht noch weitere Zauber lernen." }, enUS = { progress = "You've returned. Splendid!\n\nHow went your journey to Silverpine? Did it take you long?\n\nIt is hard for me to tell if you were successful there because so much of the land has become corrupt. Its stench overwhelms any good that you might have done. But small successes are sometimes as important as large ones. Purifying the water there was instrumental for you, and for all shamans.", completion = "This is the proof I asked for. You've done well, {name}.\n\nI am pleased to be the first to congratulate you and give you this... your water totem.\n\nUse it well, and good luck.\n\nYour next test will not be for some time, so learn your lessons well. Pure water will not only give life back to those who are injured, but can have many other effects. I suggest you seek out a {class} trainer when you have the time. They might have other spells for you to learn." } })
apply(97, { "classic", "forever" }, { deDE = { completion = "Ich wusste es! Gute Arbeit, {name}." }, enUS = { completion = "I knew it!  Fine work, {name}." } })
apply(98, { "classic", "forever" }, { deDE = { progress = "Ja, {name}?", completion = "Ich weiß es bereits, {name}: Stalvan ist tot. Ich spürte, wie eine Woge der Hoffnung durch den verseuchten Wald ging. Nun ist der Dämmerwald für alle Zeiten von Stalvans Blutdurst befreit. Meine Freude wird getrübt durch den Gedanken an all diejenigen, die diesem schrecklichen Monster zum Opfer gefallen sind. Doch wie dem auch sei. Ihr, {class}, seid mutig und geschickt und ich danke Euch." }, enUS = { progress = "Yes, {name}?", completion = "I know, {name}: Stalvan is dead.  I sensed a wave of hope ripple through the tainted forest.  Once and for all, Duskwood is free from his blood thirst.  My joy is hampered by thoughts of those who fell prey to the horrible beast.  Nonetheless, you are a brave and cunning {class}." } })
apply(99, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Pyrewood-Fesseln schon sichergestellt, {name}?", completion = "Euere Hartnäckigkeit ist lobenswert. Dank des Wissens, das zu beschaffen Ihr mir geholfen habt, wird Arugal untergehen und seine leichtsinnige Magie zunichte gemacht werden. Meinen Beifall, {name}." }, enUS = { progress = "Have you secured the Pyrewood Shackles yet, {name}?", completion = "Your persistence is commendable.  With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone.  Cheers to you, {name}." } })
apply(100, { "classic", "forever" }, { deDE = { completion = "Dank Euch. Dank den Schamanen.\n\nDie Verderbnis weicht, aber das Leben schwindet weiter. Es ist an den Schamanen, Leben zu schützen." }, enUS = { completion = "Thanks to you. Thanks to the shamans.\n\nCorruption ebbs but life continues to wane. Up to shamans to protect life." } })
apply(101, { "classic", "forever" }, { deDE = { progress = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva. Ich werde Euch ein Totem des Gegenschlages herstellen und es mit einem Zauber belegen, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", completion = "Das war sehr klug von Euch, {name}. Dieses Totem des Gegenschlages wird Euch gegen das Böse beschützen, das in ganz Azeroth und darüber hinaus lauert. Wenn Ihr Euch bedroht fühlt, dann haltet dieses Totem hoch und fühlt Euch von seiner magischen Aura getröstet. Seid tapfer, edler {class}. Ihr werdet allen Mut brauchen, den Ihr aufbringen könnt, denn ich sehe viel Blutvergießen in Eurer Zukunft." }, enUS = { progress = "Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", completion = "Very wise of you, {name}.  This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond.  When you feel threatened, hold this totem and take comfort in its magical aura.  Be brave, fair {class}.  You will need all the courage you can muster for I see much bloodshed in your future." } })
apply(102, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits 8 Tatzen dieser verräterischen Gnolle erlangt?", completion = "Gut gemacht, {name}. Wenn tapfere Abenteurer wie Ihr selbst weiter Seite an Seite mit der Volksmiliz kämpfen, ist es durchaus möglich, dass Westfall wieder zu der reichen Kornkammer werden könnte, die es einmal war. Bitte nehmt dies in Anerkennung Eurer unermüdlichen Anstrengungen entgegen." }, enUS = { progress = "Have you collected 8 paws from those treacherous Gnolls yet?", completion = "Well done, {name}.  With valiant adventurers such as yourself fighting alongside The People's Militia, Westfall just might return to the prosperous breadbasket it once was.  Please accept this in recognition of your tireless efforts." } })
apply(103, { "classic", "forever" }, { deDE = { progress = "Ohne Öl wird die Flamme nicht lange brennen, {name}.", completion = "Ein Hoch auf Eure Tapferkeit, {class}. Die Felsen entlang der Küste von Westfall werden dank Eurer harten Arbeit wieder hell erleuchtet sein. Die Fackel wird viele Leben retten, solange sie weiterbrennt.\n\nAn eben diesem Strand starb ich einen sinnlosen Tod. Jetzt, nach meinem Tod, ist es meine Bürde, sicherzustellen, dass niemand anderes dasselbe Schicksal erleiden muss." }, enUS = { progress = "The flame will not burn for long without oil, {name}.", completion = "Praise you, brave {class}.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny." } })
apply(104, { "classic", "forever" }, { deDE = { progress = "Habt Ihr der Bedrohung namens Old Murk-Eye schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Murk-Eye, dieser garstige Heide, endlich tot. Gut gemacht, {name}. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein." }, enUS = { progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, {name}.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics." } })
apply(107, { "classic", "forever" }, { deDE = { progress = "Ihr habt da eine Nachricht von \"Oma\" Stonefield, hm? Ich habe Mildred schon seit Jahren nicht mehr gesehen! Ich frage mich, was so wichtig ist, dass sie mir schreibt...", completion = "Maybell und Tommy Joe, diese armen Kinder, haben mein ganzes Mitgefühl. Ich kann mich noch gut daran erinnern, wie ich mich einst fühlte, als ich selbst noch jung und verliebt war...\n\nEs muss doch etwas geben, das ich tun kann, um ihnen zu helfen! Lasst mich einen Moment nachdenken..." }, enUS = { progress = "You have a note from \"Gramma\" Stonefield, eh?  I haven't seen Mildred in years!  I wonder what she has to say...", completion = "My heart goes out to those two poor souls, Maybell and Tommy Joe.  I remember being young and in love, once.\n\nThere must be something I can do to help them!  Let me think..." } })
apply(109, { "classic", "forever" }, { deDE = { completion = "Ah, mein Freund hat Euch also zu mir geschickt? Wie nett. \n\nNun, das Königshaus von Stormwind hat unsere Sache aufgegeben. Jetzt ist es an der Volksmiliz, das Land von der Verderbnis zu befreien. Wenn Euch unsere Sache interessiert, so würde ich Eure Fertigkeit im Kampf gern im Namen der Freiheit einsetzen." }, enUS = { completion = "Ah, so my friend sent you here?  How kind.  \n\nWell the Stormwind Monarchy has abandoned our cause.  Now it is up to the People's Militia to keep the land free from corruption.  If our cause interests you, I can put your combat skills to use in the name of freedom." } })
apply(110, { "classic", "forever" }, { deDE = { completion = "Ja, ich habe die Ergebnisse direkt vor mir. Sie sind... gelinde gesagt, beunruhigend.\n\nUnser Anfangsverdacht, dass die Käfer durch eine äußere Macht kontrolliert werden, war wohl richtig. Falls das zutrifft, dann haben wir es nicht nur mit einer sehr starken unbekannten Macht zu tun, sondern auch noch mit einer bösartigen. Diese Käfer wurden in absolut verheerende Wesen verwandelt. Ich habe so etwas noch nie gesehen." }, enUS = { completion = "Yes, I have the results right here.  They are... unsettling, to say the least\n\nOur initial suspicion that the bugs are being controlled by an outside force, we believe, is correct.  If this is the case, then we are dealing with not only a very powerful unknown force, but also a malignant one.  These bugs have been changed to be pure ravagers.  I've never seen anything quite like it." } })
apply(111, { "classic", "forever" }, { deDE = { completion = "Solange die Feindschaft zwischen unseren Familien besteht, sehe ich keine gemeinsame Zukunft für Tommy Joe und Maybell... Aber vielleicht können wir sie ja wenigstens für kurze Zeit zusammenbringen.\n\nHmm, was kann man da machen..." }, enUS = { completion = "While our families are feuding, Tommy Joe and Maybell don't have much of a future, but... maybe we can get them together for just a little while.\n\nHm, what can we do..." } })
apply(112, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Kristalltang? Ich bin mir sicher, Maybell kann es kaum erwarten, zu ihrem Verehrer zu kommen.", completion = "Ihr habt den Tang bekommen. Ausgezeichnet! Wartet noch einen kleinen Moment, während ich den Trank braue..." }, enUS = { progress = "Do you have that crystal kelp?  I'm sure Maybell is anxious to see her beau...", completion = "You got them.  Good show!  Now, just one moment while I concoct the potion..." } })
apply(113, { "classic", "forever" }, { deDE = { progress = "Na, Unterfeldmesser {name}, hat der alte Pestlezugg diesen Bericht schon fertig?", completion = "Vielen Dank für die Überbringung des Berichts, Unterfeldmesser {name}, hier ist Eure Bezahlung für den gewissenhaften Dienst an der Gadgetzan Water Company.\n\nIch bin zwar normalerweise nicht begeistert von dem Gedanken, unsere wertvollen Informationen einfach so an diejenigen weiterzugeben, die anderenfalls gutes Geld dafür bezahlen würden, aber ich kenne Pestlezugg jetzt schon etliche Jahre. Wenn er empfiehlt, jeden darüber zu informieren, dann soll es so sein. Gebt mir einen Augenblick und ich werde Euch eine Kopie erstellen." }, enUS = { progress = "Well Junior Surveyor {name}, has ol' Pestlezugg got that report ready yet?", completion = "Thank you for delivering the report, Junior Surveyor {name}; here is your pay for your diligent service to the Gadgetzan Water Company.\n\nWhile I am usually not thrilled about handing out our valuable information carte blanche to those who would otherwise pay good coin for it, I've known Pestlezugg for a number of years now.  If he recommends letting everyone know about it, then so be it.  Give me a moment and I'll make you a copy." } })
apply(114, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Tommy Lee meinen Brief überbracht? Was hat er gesagt?", completion = "Ach du liebe Zeit! Ich fühle mich schuldig, weil ich meine Familie täuschen muss, aber meine Gefühle für Tommy Joe sind einfach zu stark. Ich kann sie nicht ignorieren.\n\nIch danke Euch, {name}. Ich werde den Schnaps trinken, sobald ich eine Möglichkeit dazu habe, und mich zu meinem Liebsten schleichen.\n\nUnd Ihr... bitte nehmt dies." }, enUS = { progress = "Did you deliver my letter to Tommy Joe?  What did he say??", completion = "Oh...my!  I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.\n\nThank you, {name}.  I'll drink this liquor as soon as I have the chance and sneak away to my love.\n\nAnd for you... please take this." } })
apply(115, { "classic", "forever" }, { deDE = { progress = "Wie verläuft Euer Kampf gegen die Schattenzauberer? Habt Ihr die Mitternachtskugeln gefunden?", completion = "Ich danke Euch, {name}. Ich werde diese Kugeln umgehend ihrer Beseitigung zuführen." }, enUS = { progress = "How goes your conflict with the shadowcasters?  Did you find the midnight orbs?", completion = "Thank you, {name}.  I'll send these to be destroyed immediately." } })
apply(116, { "classic", "forever" }, { deDE = { progress = "Ihr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch süßen Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", completion = "Sehr gute Arbeit, {name}! Ich weiß sehr wohl, welch weite Wege Ihr zurücklegen musstet, um diese beeindruckende Batterie an geistigen Getränken zu beschaffen. Aber meine Kunden haben endlich wieder Grund zur Zufriedenheit. \n\nMeine Frau ist eine ausgezeichnete Näherin. Bitte nehmt als Dank für Eure Dienste diesen von ihr gefertigten Umhang an." }, enUS = { progress = "I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", completion = "A job well done, {name}!  I know well the roads you had to journey to procure this fine array of liquor.  But my patrons will be happy once again! \n\nMy wife is quite a seamstress.  Please accept this cloak she made in return for your services." } })
apply(118, { "classic", "forever" }, { deDE = { progress = "Wie meint Ihr? Verner hat Euch geschickt, sagt Ihr? Na, dann gebt mir seine Nachricht. Und SPRECHT LAUTER!", completion = "Hehe, der alte Verner braucht also ein paar Hufeisen, wie?" }, enUS = { progress = "What's that?  Verner sent you, you say?  Well give me his note.  And SPEAK UP!", completion = "Heh, so old Verner needs some shoes, does he!?!" } })
apply(119, { "classic", "forever" }, { deDE = { progress = "Oh, gut, Ihr seid zurück! Habt Ihr die Hufeisen bekommen?", completion = "Vielen Dank, das hilft mir wirklich weiter.\n\nAber was haben wir denn da? Der Kiste liegt eine Nachricht bei, die hat wohl Argus mitgeschickt... WAS? Argus will, dass ich ihn BEZAHLE? Pah!\n\nNa gut, jedenfalls danke für Eure Hilfe, {name}." }, enUS = { progress = "Great, you're back!  Did you get the shoes?", completion = "Thank you, this really helps me out.\n\nBut what's this?  Argus sent a note with the crate...What??  Argus wants me to PAY him?  Bah!\n\nWell, {name}, thank you for your help." } })
apply(120, { "classic", "forever" }, { deDE = { progress = "Was bringt Ihr mir da?", completion = "Rührt Euch, {class}.\n\nMagistrat Solomon ist ein guter Anführer, und seine Worte haben großes Gewicht für mich. Ich werde um eine Audienz beim König ersuchen und ihm die Lage verdeutlichen. Versichert dem guten Richter, dass er sich der Unterstützung der Armee von Stormwind gewiss sein kann. Ich werde Verstärkung entsenden, sobald Seine Majestät den Befehl dazu gibt." }, enUS = { progress = "What have you there?", completion = "At ease, {class}.\n\nMagistrate Solomon is a noble leader.  His words carry great weight with me.  I shall seek the counsel of the King and make the situation clear to him.  Assure the good judge that he has the Stormwind Army's support.  Reinforcements will be sent as soon as word is given from His Majesty." } })
apply(121, { "classic", "forever" }, { deDE = { progress = "Sendet der General Nachricht? Ist Verstärkung unterwegs?", completion = "Ich danke Euch für die Zeit, die Ihr aufgewendet habt, {class}. Für Eure Dienste an Seenhain und Stormwind belohne ich Euch mit diesen Münzen.\n\nWenn Ihr mich jetzt entschuldigen wollt, diese Depesche stellt mich vor ein gewisses Rätsel. Irgendetwas stimmt in unserem Königreich nicht. Ich fürchte, dies ist erst der Anfang des Kampfes, nicht dessen Ende." }, enUS = { progress = "Did the General send news?  Are reinforcements on the way?", completion = "Thank you for your time, {class}.  For your service to Lakeshire and Stormwind I reward you with these coins.\n\nNow if you'll excuse me, I find this correspondence somewhat of a mystery.  Something is amiss in our Kingdom.  I fear this is the beginning of conflict, not the end." } })
apply(122, { "classic", "forever" }, { deDE = { progress = "Ich weiß, dass dieser Gierhals Argus jemanden schicken wird, um die Schuppen für ihn einzutreiben, wenn ich sie ihm nicht bald von mir aus gebe. Habt Ihr die Schuppen schon gefunden?", completion = "Danke! So werde ich meine Schulden Argus gegenüber los." }, enUS = { progress = "I know that greedy Argus will send someone to collect his scales if I don't give them to him soon.  Have you found those scales yet?", completion = "Thanks!  These will get me out of debt to Argus..." } })
apply(123, { "classic", "forever" }, { deDE = { progress = "Was?!? Schon seit Monaten arbeiten unsere Leute nicht mehr in den Minen von Elwynn!\n\nZeigt mir mal diese Notiz, die Ihr da habt...", completion = "Hm... Ich habe von diesem \"Sammler\" schon gehört, aber ich weiß nicht, für wen er arbeitet. Vielen Dank für diesen Zeitplan. Er wird uns dabei helfen, das Rätsel zu lösen." }, enUS = { progress = "What?!?  We haven't had our people working the Elwynn mines for months!\n\nLet me see that note you have...", completion = "Hm... I have heard of this \"Collector\" but I don't know whom he's working for.  Thank you for the schedule.  It will help us solve this mystery." } })
apply(124, { "classic", "forever" }, { deDE = { progress = "Meine Pferde sind immer noch nervös und nachts höre ich immer noch dieses verfluchte Wolfsgeheul. Bitte tut etwas gegen diese Gnolle, {name}!", completion = "Danke für all Eure Hilfe, {name}." }, enUS = { progress = "My horses still seem skittish, and I still hear that cursed wolf cry at night.  Please, {name}, do something about those Gnolls!", completion = "Thank you for all your help, {name}." } })
apply(125, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Werkzeuge finden können?", completion = "Das habt Ihr gut gemacht, {name}! Ich hätte nie gedacht, dass ich diese Werkzeuge jemals wiedersehen würde." }, enUS = { progress = "Were you able to find my tools?", completion = "Excellent recovery, {name}!  I never thought I'd see these tools again." } })
apply(126, { "classic", "forever" }, { deDE = { progress = "Jauler ist gefährlich, {name}. Wenn Ihr Euch ihm noch nicht gewachsen fühlt, dann verstehe ich das.", completion = "Nochmals danke für Eure Hilfe. Die Armee von Stormwind ist so sehr mit den Orcs beschäftigt, dass sie nicht genügend Truppen hat, um das Rotkammgebirge vor kleineren Bedrohungen wie den Gnollen zu beschützen." }, enUS = { progress = "Yowler is a dangerous creature, {name}.  If you're not ready for him, I understand.", completion = "Again, thank you for your help.  The Stormwind army is so busy dealing with the orcs, they don't have the troops to protect Redridge from local threats like the gnolls." } })
apply(127, { "classic", "forever" }, { deDE = { progress = "Ihr habt wohl'n paar Sonnenfische für mich, hm?", completion = "Schön, mit Euch Geschäfte zu machen, Kumpel!" }, enUS = { progress = "You have some sunfish for me, eh?", completion = "Pleasure doin' business with you, matey!" } })
apply(128, { "classic", "forever" }, { deDE = { completion = "Wie ich sehe, habt Ihr tapfer gegen den Blackrockklan gekämpft, {class}. Ihr habt unserem Ort wahrlich einen großen Dienst erwiesen." }, enUS = { completion = "I see you have fought valiantly against the Blackrock Clan, {class}.  Your service to our township is great indeed." } })
apply(129, { "classic", "forever" }, { deDE = { progress = "So, Darcy hat mir ein Mittagessen geschickt, wie? Sie hat wirklich ein gutes Herz. Na, dann mal her damit!", completion = "Vielen Dank, das Essen hatte ich jetzt wirklich nötig. Seenhain gegen die Orcs und Gnolle zu beschützen strengt ganz schön an." }, enUS = { progress = "Darcy sent me a lunch, did she?  Such a kind heart she has.  Well...let's have it!", completion = "Thanks, I could really use the meal.  Guarding Lakeshire from the orcs and gnolls is tough work!" } })
apply(130, { "classic", "forever" }, { deDE = { completion = "Ihr braucht einen Blumenstrauß? Ihr seid noch nicht sehr lange in der Stadt - habt Ihr Euch etwa schon eine Liebste angelacht?\n\nIch weiß, es gehört sich nicht, so neugierig zu sein, aber ich finde es einfach schön, dass Liebe in der Luft liegt... vor allem in gefährlichen Zeiten wie diesen." }, enUS = { completion = "You need a bouquet of flowers?  You haven't been in town very long...have you already found for yourself a sweetheart here?\n\nI know I shouldn't pry, but it's nice to see that love is in the air... especially in dangerous times like these." } })
apply(131, { "classic", "forever" }, { deDE = { progress = "Da seid Ihr ja wieder, {name}. Hat Parker das Mittagessen geschmeckt, das ich ihm geschickt habe?", completion = "Die Blumen sind wunderschön! Ich kann es kaum erwarten, sie ins Wasser zu stellen.\n\nAber wartet mal... das sind ja die Lieblingsblumen von Martie! Parker hat Euch doch wohl nicht etwa zu diesem missgünstigen Drachen geschickt, um die Blumen zu besorgen! Ihr habt ihr doch hoffentlich nicht gesagt, für wen die waren, oder? Falls doch, dann würde es mich nicht wundern, falls Martie die Blumen irgendwie vergiftet hätte.\n\nAber da könnt Ihr ja nichts dafür. Vielen Dank - und hier habt Ihr auch Euer Essen." }, enUS = { progress = "Hello again, {name}.  Did Parker like the lunch I sent him?", completion = "Oh, those are lovely!  I can't wait to put them in some water!\n\nBut...these are Martie's favorite flowers.  Parker didn't have you go to that jealous vixen for this bouquet, did he?  You didn't tell her who they were for, did you?  If you did, then it wouldn't surprise me if she poisoned them.\n\nOh, but it's not your fault.  Thank you, and here's your meal." } })
apply(132, { "classic", "forever" }, { deDE = { progress = "Schön, dass Ihr zurück seid, {name}. Was hatte Wiley zu seiner Verteidigung zu sagen?", completion = "Pah! Ich hätte den Halunken verfaulen lassen sollen, als ich die Chance dazu hatte. Aber diese Informationen sind von äußerster Wichtigkeit. Gute Arbeit." }, enUS = { progress = "Good to see you back, {name}.  What did Wiley have to say for himself?", completion = "Bah!  I should have let that scoundrel rot when I had the chance.  But this information is crucial.  Good work." } })
apply(133, { "classic", "forever" }, { deDE = { progress = "Ich glaube, hinter dem Haus treibt sich ein Rudel Ghule herum - je schneller ich das Bildnis aufstelle, desto besser! Habt Ihr die Ghulrippen für mich?", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben." }, enUS = { progress = "I think I hear a pack of Ghouls scurrying around the back of the house - I better put that effigy up quick!  Did you get those Ghoul Ribs for me?", completion = "Ah, thanks.  These will do just the trick!" } })
apply(134, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, {name}! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!" }, enUS = { progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, {name}!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!" } })
apply(135, { "classic", "forever" }, { deDE = { progress = "Was wollt Ihr von mir? Ich bin ein viel beschäftigter Mann...", completion = "Diese Angelegenheit ist vermutlich komplizierter, als Stoutmantle ahnt." }, enUS = { progress = "What business do you have with me?  I am a very busy man. . .", completion = "This matter might be more complex than Stoutmantle realizes." } })
apply(136, { "classic", "forever" }, { deDE = { completion = "Langsam und quietschend öffnet sich die Schließkiste. Erst scheint es, als bestünde ihr Inhalt allein aus Wasser und Sand. Aber halt! Ein kleiner Krebs huscht heraus, der einen Hinweis auf den Schatz in seinen Scheren trägt!" }, enUS = { completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!" } })
apply(141, { "classic", "forever" }, { deDE = { progress = "Konnte Meister Shaw etwas Licht auf die Dinge werfen?", completion = "Edwin van Cleef... dieser Name ist mir wohl bekannt. Ein so talentierter und fleißiger Mann soll zu einem solchen Schurken geworden sein?... Der Gedanke erschreckt mich und ich brauche weitere Beweise, ehe ich das glaube." }, enUS = { progress = "Did Master Shaw shed any light on things?", completion = "Edwin VanCleef. . .I know the name well.  To think that a man so industrious and talented could turn into such a scoundrel unnerves me.  I'll need further proof before I believe this." } })
apply(142, { "classic", "forever" }, { deDE = { progress = "Habt Ihr irgendetwas erfahren können, {name}? Habt Ihr den Boten gefunden?", completion = "Dies beweist allerdings eindeutig, dass van Cleef das Kommando hat. Jetzt müssen wir nur noch herausfinden, wo die Bande der Defias sich versteckt hält.\n\nWährend Ihr fort wart, gab es hier einen Glücksfall. Wir haben einen Dieb gefasst, der Saldeans Wagen stehlen wollte. Er hat versprochen, uns zu dem Versteck zu führen, wenn wir im Gegenzug sein Leben verschonen. Ich möchte, dass Ihr den Verräter schützt, damit er uns das Versteck zeigen kann. Kehrt zu mir zurück, sobald Ihr den Ort gefunden habt." }, enUS = { progress = "{name}, were you able to gather any information?  Did you locate the messenger?", completion = "This is indeed firm proof that VanCleef is in charge.  Now all we need to know is where the Defias gang is hiding out.\n\nWe've had a stroke of luck while you were gone.  We captured a thief trying to steal Saldean's wagon.  He has promised to lead us to the hideout in exchange for his life.  I want you to defend the traitor so he can reveal the hideout.  Return to me once you have uncovered the location." } })
apply(143, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}! Welcher Anlass führt Euch zur Volksmiliz?", completion = "Werter Bote, Ihr habt Eurem Meister wohl gedient." }, enUS = { progress = "Hail, {class}.  What business do you have with The People's Militia?", completion = "Good Messenger, you have served your master well." } })
apply(144, { "classic", "forever" }, { deDE = { progress = "Dürfen wir die Volksmiliz bald erwarten? Lassen Lord Stoutmantles Nachrichten Gutes erhoffen?", completion = "Ich muss schon sagen, dies klingt überhaupt nicht gut. Ich wusste nicht, dass die Lage, in der Stoutmantle sich befindet, der unseren hier in Seenhain nicht unähnlich ist. Was kann nur so wichtig sein, dass es die Armee von Stormwind davon abhält, dem Volk, das sie beschützen soll, zu Hilfe zu eilen? Aber ich sollte nicht laut grübeln.\n\nHier, Bote. Nehmt diese Münzen als Bezahlung für Eure Verdienste um die Stadt entgegen. Es wäre möglich, dass ich Eure Hilfe ein weiteres Mal benötige." }, enUS = { progress = "Shall we expect the People's Militia soon?  Does Lord Stoutmantle's news bode well?", completion = "I do say, this is not good at all.  I did not realize that Stoutmantle's situation was not unlike ours here in Lakeshire.  What action is so important that it calls the Stormwind Army away from its people?  Bah, I should not ponder aloud.\n\nHere, messenger.  Accept these coins in exchange for your service to the Township.  I might call upon you again." } })
apply(145, { "classic", "forever" }, { deDE = { progress = "Es scheint mir, als wäret Ihr weit gereist, {class}. Was ist Euer Begehr hier in Dunkelhain?", completion = "Ich danke Euch, dass Ihr die lange Reise hierher unternommen habt. Dies sind wirklich wichtige Informationen." }, enUS = { progress = "You appear to have traveled from afar, {class}.  What business do you have here in Darkshire?", completion = "Thank you for making the long journey here.  This is indeed important information." } })
apply(146, { "classic", "forever" }, { deDE = { progress = "Ah, gut, Ihr seid von Eurem Botengang zurück. Kann ich den Marshal informieren, dass die Nachtwache von Dunkelhain hierher unterwegs ist?", completion = "Beim Licht! Die Armee von Stormwind hat sich aus Westfall zurückgezogen und die Wache beschützt Dunkelhain nicht mehr? Hier ist Verrat im Spiel. Wie konnte dies geschehen? \n\nDoch ich vergaß, Euch für Eure Dienste zu belohnen, {class}. Hier habt Ihr einige Münzen. Und nun entschuldigt mich. Etwas stimmt nicht in Stormwind und ich muss der Sache auf den Grund gehen." }, enUS = { progress = "Ah, good to see you back, messenger.  Shall I inform the Marshal that the Night Watch is on its way from Darkshire?", completion = "By the Light!  The Stormwind Army retreated from Westfall.  And the Guard no longer protects Darkshire?  There is some treachery abound.  How could this be so? \n\nOh I forgot to reward your service, {class}.  Here are some coins.  Now excuse me.  Something is amiss in Stormwind and I must get to the bottom of it." } })
apply(147, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Sammler gefunden? Konntet Ihr herausfinden, für wen er arbeitet?", completion = "Ihr habt ihn gefunden? Gut gemacht, {name}. Der wird in den Minen von Elwynn nichts mehr \"einsammeln\"!\n\nUnd dieser Ring, den Ihr gefunden habt, ist auch sehr interessant. Es ist ein Gildenring der alten Steinmetzgilde aus Stormwind. Warum hat ein nichtswürdiger Dieb den Ring einer Handwerkergilde in seinem Besitz und warum treibt die Bruderschaft der Defias Geld aus unseren Minen ein?\n\nDas sind schwierige Fragen, und ich hoffe nur, wir werden eines Tages die Antworten darauf finden." }, enUS = { progress = "Did you find the Collector?  Did you discover whom he's working for?", completion = "You found him?  Well done, {name}.  He won't be \"collecting\" from the Elwynn Mines again!\n\nAnd this ring you found is interesting... it's a membership ring for the old Stonemason's Guild in Stormwind.  Why would a lowly thief have an artisan guild ring, and why are the Defias Thieves collecting money from our mines?\n\nDifficult questions.  I hope one day we'll have answers." } })
apply(148, { "classic", "forever" }, { deDE = { completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt." }, enUS = { completion = "Ah, Ghost Hair Thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair." } })
apply(149, { "classic", "forever" }, { deDE = { progress = "<Schluchz> Oh bitte, seht mich nicht an! Ich habe mir diese Augen mit meinen eigenen Händen herausgerissen, aber Euren Blick kann ich immer noch spüren!\n\nIch sehe grauenhaft aus! Grauenhaft! Ich flehe Euch an, wendet Euren Blick ab!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es nicht so entsetzlich verklebt und strähnig, wie es ist.\n\nAch, wenn ich doch nur einen Spiegel hätte..." }, enUS = { progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror..." } })
apply(150, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Flossen? Sputet Euch - diese Murlocs müssen vom See vertrieben werden!", completion = "Gut gemacht, {name}. Ich hoffe, diese Murlocs haben Euch nicht zu viele Schwierigkeiten bereitet.\n\nEs ist seltsam, dass man sie so weit vom Meer entfernt sieht. Ich frage mich, ob sie hier sind, weil sie vor etwas davonlaufen..." }, enUS = { progress = "Do you have those fins?  Hurry, we need those murlocs driven from the lake!", completion = "Well done, {name}.  I hope you didn't have too much trouble with those murlocs.\n\nIt's strange seeing them so far from the sea.  I wonder if they're here because they're running from something..." } })
apply(151, { "classic", "forever" }, { deDE = { progress = "Graumähne kann sich kaum noch auf den Beinen halten. Habt Ihr zufällig etwas Hafer für sie finden können?", completion = "Vielen herzlichen Dank, {name}! Da wird sich die gute Graumähne aber freuen!" }, enUS = { progress = "Old Blanchy is on her last leg.  Did you happen to find any oats for her?", completion = "Thank you so much, {name}!  Poor Old Blanchy will be so happy!" } })
apply(152, { "classic", "forever" }, { deDE = { progress = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", completion = "Gut gemacht, {name}. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor." }, enUS = { progress = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", completion = "Well done, {name}.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place." } })
apply(153, { "classic", "forever" }, { deDE = { progress = "Bringt mir 15 rote Lederkopftücher, ich werde Euch gut dafür bezahlen.", completion = "Gute Arbeit, {race}. Bitte nehmt einen dieser Gegenstände als Bezahlung für Eure harte Arbeit an." }, enUS = { progress = "Bring me 15 red leather bandanas and I'll pay you well.", completion = "Nice work, {race}.  Please accept one of these items as payment for all your hard work." } })
apply(154, { "classic", "forever" }, { deDE = { progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare." }, enUS = { progress = "I sense that you have seen Blind Mary.  You have my Comb...?", completion = "I can make a spool of Ghost Hair Thread with this, and have a few strands to spare.  Here are some coins for those extra strands." } })
apply(155, { "classic", "forever" }, { deDE = { completion = "Ganz ausgezeichnet, {name}! Jetzt, wo wir wissen, wo er sich versteckt, gehört van Cleef so gut wie uns." }, enUS = { completion = "Most excellent, {name}!  VanCleef is as good as ours now that we know where he is hiding." } })
apply(156, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die Faulblüten für mich?", completion = "Oh gut, Ihr habt die Faulblüten bekommen. Und ich werde Althea Ebonlocke von der Nachtwache erzählen, dass Ihr etliche Skelette getötet habt.\n\nDie Bevölkerung von Dunkelhain zu beschützen, stellt für die Nachtwache eine schwere Aufgabe dar und das Wissen, dass es auch andere gibt, die die Flut der Unwesen einzudämmen helfen, ist für sie eine willkommene Nachricht." }, enUS = { progress = "Hi, {name}.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.  And I'll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.\n\nKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed." } })
apply(157, { "classic", "forever" }, { deDE = { progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter {name}, nehmt dies als Bezahlung für Eure ehrenhafte Tat." }, enUS = { progress = "I need to string the Ghost Hair Thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good {name}, take this as payment for your honorable deed." } })
apply(158, { "classic", "forever" }, { deDE = { completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt." }, enUS = { completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it." } })
apply(159, { "classic", "forever" }, { deDE = { progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, {name}! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit." }, enUS = { progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, {name}.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude." } })
apply(160, { "classic", "forever" }, { deDE = { progress = "Calvinius...? Ich kenne niemanden dieses Namens. Ihr sagt, Ihr habt einen Brief für mich von diesem Calvinius?\n\nNa, dann lasst mal sehen...", completion = "<Ello sieht sich den Brief an...>\n\nWas für eine Sprache ist das? Sie sieht uralt aus... ich kann sie nicht lesen." }, enUS = { progress = "Abercrombie...?  I don't know a person of that name.  You say you have a letter for me from this Abercrombie fellow?\n\nWell let's have it then...", completion = "<Ello looks at the letter...>\n\nWhat language is this?  It looks ancient...I can't read it." } })
apply(161, { "classic", "forever" }, { deDE = { progress = "Habt Ihr was gesagt, Jungchen? Ich kann nix hören außer dem verdammten Dröhnen in den Ohren. Sagt mal, was habt Ihr denn da?", completion = "Ah ja, also da hat der Olle Hinderweir verdammt Recht, dass er sich Sorgen macht." }, enUS = { progress = "You say somethin', sonny?  Can't hear a bloody thing besides the ringin' in me ears.  Say, what's that you got there?", completion = "Ah, well Ol' Hinderweir is wise to be worried." } })
apply(162, { "classic", "forever" }, { deDE = { progress = "Friede und Gelassenheit sei mit Euch, Fremdling. Warum habt Ihr mich heute aufgesucht?", completion = "Dieser Bericht... wir Nachtelfen kennen den Schrecken, der hier erwähnt wird. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, {name}: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen." }, enUS = { progress = "Peace and tranquility be on to you, stranger.  Why have you sought me out this day?", completion = "This report... we night elves know of the terror mentioned here.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, {name}: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before." } })
apply(163, { "classic", "forever" }, { deDE = { completion = "Nein! Bitte tötet mich nicht! Ich bin's doch nur... Jitters! Sie sind überall... Ich kann ihnen nicht entkommen! Monster in Rabenflucht? N-n-n-nein... das kann gar nicht sein. Nur der harmlose Jitters." }, enUS = { completion = "No! Please don't kill me! It's just me... Jitters!! They're everywhere... I can't escape them! Monsters in Raven Hill? N-n-n-o... couldn't be. Only harmless Jitters." } })
apply(164, { "classic", "forever" }, { deDE = { progress = "Ihr seht ziemlich robust aus, {class}. Wollt Ihr Euch unserem Kampf anschließen?", completion = "Diese Vorräte werden sich als äußerst nützlich erweisen. Wir wissen die Hilfe der Familie Carevin stets zu schätzen. Hier habt Ihr etwas für Eure Mühe." }, enUS = { progress = "You look a sturdy type, {class}. Have you come to join our fight?", completion = "These supplies will be most useful. The aid of the Carevin family is always appreciated. Here is a little something for your trouble." } })
apply(165, { "classic", "forever" }, { deDE = { completion = "Elaine Carevin? Hehe, ja, aber natürlich... die Carevins.\n\nDoch, doch, es ist alles in Ordnung, aber es ist inzwischen ziemlich schwer für mich, in die Stadt zu kommen. Die Straßen sind gefährlich und ich werde nicht jünger. Vielleicht könntet Ihr ja einem alten Mann ein paar Gefallen tun?" }, enUS = { completion = "Elaine Carevin? Hehe, oh yes... of course, the Carevins.\n\nNo, nothing's wrong but it is hard for me to go into town now. The roads are dangerous and I'm not getting any younger. Maybe you can do an old man some favors?" } })
apply(166, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd auf Edwin van Cleef?", completion = "Euer Mut ist bemerkenswert, {name}. Die Volksmiliz dankt Euch für Eure Verdienste um das Volk von Westfall. Van Cleefs Tod bedeutet den Anfang vom Ende für die Bruderschaft der Defias. Hoffentlich wird schon bald wieder Frieden auf den Ebenen unseres schönen Landes herrschen.\n\nIch ziehe den Hut vor Euch, werter Herr!" }, enUS = { progress = "How goes the hunt for Edwin VanCleef?", completion = "{name}, your bravery is remarkable.  The People's Militia thanks you for your service to the people of Westfall.  With VanCleef dead, this marks the beginning of the end for the Defias Brotherhood.  Hopefully some day soon peace will once again grace the plains of this fair land.\n\nI salute you, Sir!" } })
apply(167, { "classic", "forever" }, { deDE = { progress = "Habt Ihr ein Lebenszeichen von meinem Bruder finden können? Besteht Hoffnung nach all dieser Zeit?", completion = "Also haben meine Befürchtungen sich bestätigt. Mein armer Bruder... Nun, ich danke Euch dafür, dass Ihr dieses Rätsel gelöst habt, selbst wenn die Lösung eine traurige war." }, enUS = { progress = "Did you find any sign of my brother?  Is there any hope after all this time?", completion = "My suspicions were correct.  My poor brother.... Well, thank you for bringing some conclusion to this mystery, even if the conclusion was grim." } })
apply(168, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr einige der Gewerkschaftsausweise meiner alten Kameraden wiederfinden?", completion = "Danke, dass Ihr die Ausweise beschafft habt, {name}. Eure Anstrengungen helfen dabei, dass die Toten nach dieser schrecklichen Tragödie ihren Frieden finden. Ich werde dafür sorgen, dass die Familien benachrichtigt werden." }, enUS = { progress = "Were you able to retrieve any of my old co-worker's Miners' Union Cards?", completion = "Thank you for collecting these, {name}.  Your efforts will help bring peace to the dead in the wake of this tragedy.  I will see to it that the families are notified." } })
apply(169, { "classic", "forever" }, { deDE = { progress = "Was bringt Ihr mir da, {race}?", completion = "Ausgezeichnete Arbeit, {name}! Gath'llzogg führte diese Bestien in die Schlacht und war für den Tod vieler unschuldiger Menschen verantwortlich. Nun haben wir uns gerächt. Dies ist der erste Schritt zur Wiedereroberung der Burg für das Königreich Stormwind!" }, enUS = { progress = "What do you have there, {race}?", completion = "Fantastic work, {name}!  Gath'Ilzogg led those brutes into battle, killing many innocent humans.  Vindication is ours.  This is the first step in reclaiming the keep for the kingdom of Stormwind!" } })
apply(173, { "classic", "forever" }, { deDE = { completion = "Ich bin beeindruckt, {name}. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.\n\nAber es ist schon eigenartig... Es ist, als seien die Worgs plötzlich aus dem Nichts erschienen. Aber es sind ja in letzter Zeit so viele seltsame Kreaturen in unser Land gekommen, da sind auch die Worgs vermutlich nur eine unserer vielen Sorgen." }, enUS = { completion = "Impressive, {name}. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.\n\nIt is curious though... The worgen seemed to just appear out of thin air. But then, with all the other strange creatures that have moved across our borders, I suppose it's only one of many concerns." } })
apply(174, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits einen geschickten Ingenieur gefunden, der eine Bronzeröhre fertigen kann?", completion = "Diese Röhre ist perfekt, {name}. Das war der erste Schritt!" }, enUS = { progress = "Have you found a skilled engineer to create a bronze tube yet?", completion = "This is perfect, {name}.  The first step is complete!" } })
apply(175, { "classic", "forever" }, { deDE = { completion = "Doch, ja, ich besaß früher einen Handspiegel." }, enUS = { completion = "Why yes, I used to own a looking glass." } })
apply(176, { "classic", "forever" }, { deDE = { progress = "Ja, Hogger stellt für mich und meine Männer schon seit längerem ein echtes Problem dar. Habt Ihr mir etwas über die Bestie zu berichten?", completion = "Ha! Gut gemacht! Ich hatte schon befürchtet, niemand würde diesem Monster den Garaus machen!\n\nHier, bitte schön, {name}. Und danke - dieser Gnoll hat mir Kopfschmerzen vom Ausmaß der Blackrockspitze verursacht!" }, enUS = { progress = "Yes, Hogger has been a real pain for me and my men.  You have something to report about the beast?", completion = "Hah!  Well done!  I was starting to think no one would take down that monster!\n\nHere you are, {name}.  And thanks - that Gnoll was giving me a headache the size of Blackrock Spire!" } })
apply(177, { "classic", "forever" }, { deDE = { progress = "Ich habe Cog die Anfänge unseres Sternenschaugerätes gezeigt. Er war schwer beeindruckt. Habt Ihr zufällig einen Reflektor finden können?", completion = "Ganz phantastisch! Dies ist geradezu perfekt geeignet. Vielen Dank!" }, enUS = { progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!" } })
apply(178, { "classic", "forever" }, { deDE = { progress = "Ich habe durch einen Anhänger zu Euch gesprochen, sagt Ihr? Hmm... gebt ihn mir, damit ich ihn studieren kann.", completion = "Seid Euch meiner Dankbarkeit gewiss, {name}. Schon vor Wochen sandte ich die Nachricht zu den Schattenfellanhängern aus und hatte bereits an einen Fehlschlag geglaubt. Doch es scheint, als habe der Zauber nach einer erheblichen Verzögerung doch zumindest einige Anhänger erreicht.\n\nMit der Zeit hoffe ich zu lernen, wie man auch einen Angriff durch die Anhänger leiten und damit alle Schattenfellgnolle, die einen solchen Anhänger tragen, bewegungsunfähig machen kann.\n\nDoch bevor dies möglich sein wird, sind leider noch viele Stunden der Forschung vonnöten, fürchte ich." }, enUS = { progress = "I spoke to you through a pendant, you say?  Hmm...give it to me, so that I might study it.", completion = "You have my gratitude, {name}.  I sent that message to the Shadowhide Pendants weeks ago and had believed it a failure.  But it seems the spell did reach at least some pendants, after a significant delay.\n\nIn time I hope to learn how to send an attack through the pendants, to immobilize any Shadowhide Gnolls who wear them.\n\nBut before that is possible, I'm afraid that much more research is required." } })
apply(179, { "classic", "forever" }, { deDE = { progress = "Haben Euch die Wölfe Probleme gemacht? Vielleicht solltet Ihr den Klauen und Zähnen und dem, was da sonst noch so alles kratzt und beißt, ausweichen, hm?", completion = "Ah! Großartig. Das Wolfsfleisch ist gerade richtig. Ach, keine Sorge, {name}, ich vergess doch meinen Teil der Abmachung nicht! Hier, davon sollte Euch eins passen." }, enUS = { progress = "Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?", completion = "Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, {name}, I wouldn't forget my part of the bargain. Here, one of these should fit you." } })
apply(180, { "classic", "forever" }, { deDE = { progress = "Welche Neuigkeiten bringt Ihr vor dieses Gericht?", completion = "Der üble Lieutenant Fangor ist also tot? Endlich sind wir diese abscheuliche Kreatur los. Ihr seid sehr tapfer, {class}. Die Stadt Seenhain dankt Euch für Eure Hilfe." }, enUS = { progress = "What news do you bring before the Court?", completion = "So the evil Lieutenant Fangore is dead?  Good riddance to that foul creature.  You are very brave, {class}.  The Township of Lakeshire thanks you for your aid." } })
apply(181, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr Zzarc'Vul überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Das Sternenschaugerät ist vollendet! Danke, {name}. Jetzt kann ich meine Forschungen fortsetzen..." }, enUS = { progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, {name}.  Now I can continue my research. . ." } })
apply(182, { "classic", "forever" }, { deDE = { progress = "Nach allem, was ich gehört habe, kommen diese Trolle aus dem Frostmaneklan. Leider weiß ich nicht viel mehr über sie, das Euch in irgendeiner Form helfen könnte, {name}.", completion = "Aargh! Diese vom Licht verbrannten Trolle!\n\n<Er atmet tief durch und scheint sich zu beruhigen... ein bisschen zumindest.>\n\nIn der Nacht hat eine Gruppe Trolle mein Tagebuch gestohlen! Ich hätte es besser wissen müssen. Was vertraue ich auch meinem nichtsnutzigen Lehrl..." }, enUS = { progress = "From what I've learned, these trolls hail from the Frostmane clan. I'm afraid I don't know much else about them that would be of any use to you, {name}.", completion = "Argh! Those Light-blasted trolls!\n\n<He takes a few breaths and seems to settle down... a bit.>\n\nA group of them came in the night and stole my journal! I knew better than to trust that good-for-nothing appr..." } })
apply(183, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd?", completion = "Ausgezeichnet! Dann kann ich ja jetzt meine... etwas gemächlichere... Jagd wieder aufnehmen. Ich danke Euch, {name}." }, enUS = { progress = "How goes the hunt?", completion = "Excellent! I can go back to my... leisurely... hunting now. Thank you, {name}." } })
apply(184, { "classic", "forever" }, { deDE = { progress = "Ihr habt die Besitzurkunde meines Hofes? Wie schön! Einige Grobiane haben sie vor etlichen Tagen gestohlen... Ich dachte schon, ich würde sie nie wieder sehen!\n\nBitte, gebt sie mir. Wir sind auf dem Weg, Westfall zu verlassen, und so schnell werden wir nicht wiederkommen, aber wenn, dann werden wir diese Dokumente brauchen.", completion = "Vielen, vielen Dank, {name}! Wie schon gesagt, diese Gegend ist kein Ort mehr für ehrliche Leute, aber wenn die Dinge besser werden sollten, dann können wir mit dieser Besitzurkunde unser Land zurückfordern.\n\nIch habe nicht viel, was ich Euch anbieten kann, aber hier: Nehmt das." }, enUS = { progress = "You have the deed to my farm??  That's good news!  Some ruffians stole it days ago... I thought it was gone for good!\n\nPlease, let me have it.  We're on our way out of Westfall and ain't coming back any time soon, but if we do then we'll need those papers...", completion = "Loads of thanks, {name}!  As I was saying, these parts aren't fit for honest folk anymore, but if things get better, then this deed will let us reclaim our land.\n\nI don't have much to offer you, but here -- take this." } })
apply(185, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch nicht mit gutem Gewissen weiter ausbilden, {name}, solange Ihr nicht bewiesen habt, dass Ihr die jüngsten Tiger erlegen könnt.", completion = "Das habt Ihr gut gemacht, {name}. Ihr seid jetzt bereit, Euch anderen Dingen zu widmen." }, enUS = { progress = "I don't feel confident in training you further, {name}, until you have proven yourself skilled in slaying the youngest of the tigers first.", completion = "Nicely done, {name}.  You are ready to move on." } })
apply(186, { "classic", "forever" }, { deDE = { completion = "Ich bin beeindruckt, {class}. Ihr kommt recht gut voran." }, enUS = { completion = "I am impressed, {class}.  You are progressing quite well." } })
apply(188, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Jagd auf Sin'Dall?", completion = "Äußerst beeindruckend, das muss ich schon sagen! Ihr seid wahrlich ein Meisterjäger, {name}!" }, enUS = { progress = "How goes the hunt for Sin'Dall?", completion = "Most impressive, I do say!  You are a true Master Tiger Hunter, {name}!" } })
apply(189, { "classic", "forever" }, { deDE = { progress = "Ihr wart erfolgreich, hoffe ich. Die sind wirklich überall, diese Trolle. Widerliche Kerle.\n\nAch ja, da fällt mir was ein! Sagt es unbedingt auch all Euren Freunden weiter, ja? Wir können viel Hilfe gebrauchen!", completion = "Oh, ausgezeichnet, ganz ausgezeichnet. Das sollte helfen, für den Anfang zumindest...\n\n<Seine Stimme wird leiser und er murmelt irgendetwas von Gewinnspannen und Kosten.>\n\nWas denn? Seid Ihr immer noch da? Belohnung? Oh, ja, richtig... natürlich, hier, nehmt dies... das sollte mehr als genug sein." }, enUS = { progress = "You've had success I hope? All over the place, those trolls. Filthy devils.\n\nOh yes, that reminds me! Be sure to tell your friends, yes? We could use much assistance!", completion = "Oh excellent, excellent. That'll help a little, for the present...\n\n<He trails off, grumbling about profit margins and costs...>\n\nWhat? You're still here? Reward? Oh, right... of course, here, take this... it should be more than enough." } })
apply(191, { "classic", "forever" }, { deDE = { progress = "Geht und tötet 10 Panther! Zeigt uns, aus welchem Holz Ihr geschnitzt seid!", completion = "Das habt Ihr perfekt durchgeführt, {name}!" }, enUS = { progress = "Go kill 10 panthers!  Show us what you've got!", completion = "Perfectly executed, {name}!" } })
apply(192, { "classic", "forever" }, { deDE = { progress = "Was macht Ihr denn hier, {name}? Ihr solltet durch das Unterholz kriechen und versuchen, 10 Schattentatzenpanther zu töten! Ich dachte, Ihr hieltet Euch für einen Großwildjäger?", completion = "Ihr habt Eure Sache gut gemacht, {name}!" }, enUS = { progress = "What are you doing here, {name}!  You should be crawling through the brush, trying to kill 10 Shadowmaw Panthers.  I thought you fancied yourself a big game {class}?", completion = "You've done well, {name}!" } })
apply(193, { "classic", "forever" }, { deDE = { progress = "Bhag'thera ist oft so gut wie unauffindbar. Wie läuft die Jagd?", completion = "Der große Bhag'thera ist also tot! Meinen Beifall, {name}. Ihr seid wahrlich ein großer {class}." }, enUS = { progress = "Bhag'thera can prove to be an elusive beast.  How fares the hunt?", completion = "So the great Bhag'thera is dead!  Cheers to you, {name}.  You are a mighty {class} indeed!" } })
apply(194, { "classic", "forever" }, { deDE = { completion = "Sehr schön gemacht, alter Junge!" }, enUS = { completion = "Nicely done, old chap!" } })
apply(195, { "classic", "forever" }, { deDE = { completion = "Ja, so bekommt man die eine oder andere Jagdtrophäe zusammen, die man sich zu Hause über den Kamin hängen kann! Das war eine gute Jagd, {name}." }, enUS = { completion = "Now that's how you get a trophy or two over the ol' hearth!  Nice killing, {name}!" } })
apply(196, { "classic", "forever" }, { deDE = { completion = "Hoho! Sieh an, wir haben hier einen wahren Raptorentöter! Sehr schön gemacht, alter Junge!" }, enUS = { completion = "Ho ho!! We have ourselves a true raptor slayer!  Nicely done, old chap!" } })
apply(198, { "classic", "forever" }, { deDE = { progress = "Ja? Was wollt Ihr? Oh, Vorräte von den Goblins. Seltsam, dass ein {race} das Paket abliefert, normalerweise schicken sie einen ihrer eigenen Leute. Na, egal. Ihr habt die doch wohl hoffentlich nicht angefasst? Gut, gut... Wir wollen ja nicht, dass unseren Minen irgendwas passiert, oh nein.", completion = "Mit diesen Landminen können wir uns gegen diese Bestie Kurzen und seine Männer verteidigen. Danke, dass Ihr sie uns gebracht habt. Wenn Ihr noch weitere Arbeit möchtet, dann kann ich vermutlich etwas finden, was Ihr tun könntet. Dann müsstet Ihr Euch auch nicht mit diesen Goblins abgeben, wie?" }, enUS = { progress = "Yes? What do you want? Oh, supplies from the goblins. Strange seeing a {race} delivering them, usually they send their own. No matter... you didn't touch them did you? Good good... we wouldn't want anything to happen to our mines, oh no.", completion = "These land mines will help us defend ourselves from that animal Kurzen and his men. Thank you for bringing them. If you need further work, I can probably find something for you to do. And you won't have to deal with those goblins, hm?" } })
apply(199, { "classic", "forever" }, { deDE = { progress = "Habt Ihr irgendwelche Hinweise finden können, {name}?", completion = "Diese Entdeckung ist alarmierend und das ist noch milde ausgedrückt!" }, enUS = { progress = "Did you happen to discover any clues, {name}?", completion = "This is an alarming discovery, to say the least!" } })
apply(200, { "classic", "forever" }, { deDE = { completion = "Dies sind Buchhalter Herods Notizen und Aufzeichnungen.\n\nDarunter befinden sich: eine Liste mit Vorräten, die hier gelagert werden, Materialanforderungen von Colonel Kurzen sowie verschiedenste Briefe und Korrespondenz." }, enUS = { completion = "These are Bookie Herod's notes and records.\n\nAmong them are: a list of supplies within the camp, material requests from Colonel Kurzen, and various letters and correspondences." } })
apply(201, { "classic", "forever" }, { deDE = { completion = "Hmmm, dann waren die Informationen, die ich hatte, also wieder einmal richtig, wie meistens. Interessant. Na, ich denke nicht, dass die Jäger für unsere Unternehmung eine Bedrohung oder einen Störfaktor darstellen, aber vielleicht haben sie ja Bedarf an einigen unserer ausgezeichneten Produkte. Hmmm..." }, enUS = { completion = "Hmmm, so my information was correct, as usual. Interesting. Well, I don't suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products. Hmmm..." } })
apply(202, { "classic", "forever" }, { deDE = { progress = "Wage ich zu hoffen, dass Kurzen und seine Verteidiger tot sind, {name}?", completion = "Ich hatte den Berichten nicht glauben wollen, hatte kaum zu hoffen gewagt, aber Ihr bringt uns jetzt den Beweis... Kurzen und seine Führungsoffiziere sind tot. Ihr habt uns gerettet!\n\nIn diesem Dschungel wimmelt es nur so von den unterschiedlichsten Gefahren, doch keine von ihnen verfügt über die unbarmherzige Intelligenz, die Kurzen eigen war. Jetzt, wo er nicht mehr ist, können wir alle aufatmen." }, enUS = { progress = "Dare I hope that Kurzen and his defenders are dead, {name}?", completion = "I dared not believe the reports, but you bring us proof that...Kurzen and his leaders are defeated.  You have saved us!\n\nThese jungles are filled with menaces of all types, but none had the cruel intellect of Kurzen.  We may all breathe easier now that he is gone." } })
apply(203, { "classic", "forever" }, { deDE = { progress = "Ich hoffe, Ihr wart erfolgreich, {name}. Ohne Eure Hilfe können wir gegen Kurzen nicht lange durchhalten.", completion = "Gut gemacht. Der Verlust dieser Dschungelkämpfer wird den Druck, dem unser Lager ausgesetzt ist, etwas verringern.\n\nAber wollt Ihr Euch immer noch mit uns zusammentun, jetzt, wo Ihr einen Vorgeschmack darauf bekommen habt, was für einer Streitmacht wir uns gegenübersehen?" }, enUS = { progress = "I hope you've been successful in your hunting, {name}.  We won't last long against him without your help.", completion = "Well done.  The loss of those Jungle Fighters will relieve some of the pressure on our camp.\n\nBut now that you've had a taste of the forces we're up against, do you still want to throw your lot in with us??" } })
apply(204, { "classic", "forever" }, { deDE = { progress = "Ich warte auf die Arzneien und den Extrakt, {name}.", completion = "Gut gemacht, {name}. Dank dieser Arzneien werden mehr von uns am Leben bleiben und weiterkämpfen können. Und mit dem Extrakt können wir unsere eigenen Arzneien herstellen." }, enUS = { progress = "I'm waiting on those remedies and that extract, {name}.", completion = "Well done, {name}.  These remedies will keep more of us alive and in fighting shape.  And the extracts will help us create our own remedies." } })
apply(205, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Fetische bekommen, {name}? Vielleicht liegt ja in ihnen das Geheimnis von Kurzens Entartung verborgen... Ich muss es wissen!", completion = "Vielen Dank. Ich werde diese Fetische studieren und sehen, ob sie vielleicht das Geheimnis von Kurzens Wandlung zum Bösen in sich tragen." }, enUS = { progress = "Do you have those fetishes, {name}?  They might hold the secret to Kurzen's degradation...I must know!", completion = "Thank you.  I will study these fetishes and see if they hold the secret of Kurzen's fall into evil." } })
apply(206, { "classic", "forever" }, { deDE = { progress = "Ich gebe Euch meinen Segen mit auf den Weg. Denn nur Mai'Zoths Bösartigkeit kommt seiner Stärke gleich.", completion = "Ah! Ihr habt es geschafft! Ihr seid ein mächtiger Verbündeter des Guten;, {name}. Möge Eure Kraft niemals schwinden!\n\nIch werde dieses Gedankenauge studieren und versuchen herauszufinden, ob es vielleicht für die Sache des Guten verwendet werden kann. Wenn nicht... dann muss es zerstört werden." }, enUS = { progress = "I give you my blessing.  Mai'Zoth's strength is matched only by his evil.", completion = "Aha!  You've done it!  You are a great force for good, {name}, and may your strength never fade!\n\nI will study this Mind's Eye and determine if it may be used for good.  If not...then it must be destroyed." } })
apply(207, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr die Troll-Legenden? Ich muss ihre Geheimnisse erfahren!", completion = "Ich danke Euch, {name}. Ich werde diese Legenden studieren und versuchen herauszufinden, ob es eine Verbindung gibt zwischen den Trollen und dem Bösen, das Colonel Kurzen befallen hat." }, enUS = { progress = "{name}!  Do you have the troll legends?  I must know their secrets!", completion = "Thank you, {name}.  I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen." } })
apply(209, { "classic", "forever" }, { deDE = { progress = "Zähe Biester, was? Also, habt Ihr was für mich? Tut mir ja Leid, dass ich so ungeduldig bin, aber die Sache ist mir ein ziemlicher Dorn im Auge, solange sie nicht erledigt ist. Also?", completion = "Ah, gute Arbeit, gute Arbeit! Bäh, Ihr hättet sie ja wohl doch ein bisschen sorgfältiger säubern können, vor allem das... Na, egal, ganz egal! Ich danke Euch, {name}, unsere Unternehmung wird dank Eurer Hilfe zweifellos ihren Ausstoß und ihre Produktivität steigern können! Gut, gut, und nun zu anderen Angelegenheiten..." }, enUS = { progress = "Tough buggers, aren't they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?", completion = "Ah, good work, good work! Ugh, though you could have done a better job cleaning off the-- Well, no matter, no matter! My thanks to you, {name}, our operation will no doubt see increased output and productivity thanks to your help! Good good, now, onto other matters..." } })
apply(210, { "classic", "forever" }, { deDE = { progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja..." }, enUS = { progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price..." } })
apply(212, { "classic", "forever" }, { deDE = { progress = "{name}! Habt Ihr den Schenkel? Ich muss bald anfangen, ihn zuzubereiten, sonst ist das ganze Bankett ruiniert!", completion = "Ah ja, der eignet sich prächtig! Vielen, vielen Dank!\n\nWenn Ihr mich jetzt entschuldigen wollt, ich muss diesen Schenkel hacken, marinieren und für das Bankett garnieren." }, enUS = { progress = "{name}!  Do you have that haunch?  I must begin preparing it soon, or the banquet will be ruined!", completion = "Ah, this will do nicely!  Many, many thanks!\n\nNow if you'll excuse me, I must get the haunch chopped, marinated and garnished for the banquet." } })
apply(213, { "classic", "forever" }, { deDE = { progress = "Ich brauche diese Steine, {name}, egal, zu welchen Mitteln Ihr greift! Tut es einfach und erspart mir die Details!\n\nWas zählt, ist das Ergebnis, {name}, nicht mehr und nicht weniger.", completion = "Faszinierend. Dass die Kristalle mit dieser Methode gerommelt wurden, kann nur bedeuten, dass die Company sie als eine Art Treibstoff oder Katalysator verwenden will. Viel mehr als das weiß ich auch nicht. Wir werden Proben davon zu Oberchemiker Gigglefont schicken müssen." }, enUS = { progress = "I need those stones, {name}. By whatever means necessary! Just do it, don't give me the details!\n\nIt's about results, {name}, nothing more, nothing less.", completion = "Fascinating. That the crystals have been tumbled using this process can only indicate that they are planning to use them as some sort of fuel or other catalyst. I don't know much more than that. Samples will have to be dispatched to Head Chemist Gigglefont." } })
apply(214, { "classic", "forever" }, { deDE = { progress = "Habt Ihr unser Land etwas sicherer vor der Defiasbande gemacht? Wenn ja, dann zeigt mir 10 rote Seidenkopftücher zum Beweis.", completion = "Gut gemacht, {name}! Im Namen der Volksmiliz verneige ich mich vor Euch angesichts Eures Einsatzes. Bald schon werden wir, mit der Hilfe von tapferen Leuten wie Euch, dieses Land seinen Bewohnern zurückgeben können." }, enUS = { progress = "Have you been reclaiming our land from the Defias gang?  If so show me 10 Red Silk Bandanas as proof.", completion = "Well done, {name}!  On behalf of The People's Militia I salute you for your efforts.  Soon we will return this land to the people with help from brave souls like you." } })
apply(215, { "classic", "forever" }, { deDE = { completion = "Ja, es stimmt, was Thorsen Euch erzählt hat. Ihr müsst das absolut vertraulich behandeln. Einst waren wir Rebellen Colonel Kurzen bis zum Äußersten ergeben. Aber Kurzen erwies sich als so verderbt, dass unsere Loyalität ihm gegenüber sich in Zorn verwandelte. Wenn es bekannt würde, dass Gefreiter Thorsen kürzlich Verbindung zu Kurzens Männern hatte, dann würden wir ihn eines schönen Morgens mit durchgeschnittener Kehle vorfinden.\n\nMeines Wissens nach hatten nur Sergeant Yohwa, Thorsen und ich selbst Kenntnis von Thorsens Auftrag. Aber es muss noch eine weitere Person geben. Einen Verräter." }, enUS = { completion = "Yes, what Thorsen told you is true.  You must be discrete with this.  At one time, we rebels were fiercely loyal to Colonel Kurzen.  But such was Kurzen's corruption, our passion twisted into rage.   If it was made known that Private Thorsen has had recent dealings with Kurzen's men, then one night he would find himself with a slit throat.\n\nTo my knowledge, only Sergeant Yohwa, Thorsen and I were privy to Thorsen's mission.  But there must be another.  A traitor." } })
apply(216, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Kampf zu den Distelfellen getragen? Mit einem freien Weg zwischen unseren Stützpunkten erhöhen sich unsere Chancen erheblich, ganz Ashenvale für uns zu beanspruchen.", completion = "Gut gemacht, {class}, gut gemacht! Ich werde weiterhin Truppen aussenden, um die Population der Furbolgs niedrig zu halten, aber ich kann auf mindestens einen weiteren Pfad zählen, der frei von Verstrickungen der Allianz ist. Die Eroberung von Ashenvale durch die Horde ist jetzt in vollem Gang!\n\nIhr habt Euch heute Eure Bezahlung verdient. Ich ziehe den Hut vor Euch!" }, enUS = { progress = "Have you taken the fight to the Thistlefur?  With a clear path between our bases, our chances of claiming the whole of Ashenvale increase dramatically.", completion = "Well done {class}, well done!  I will continue to send forces to thin out the furbolg, but I can at least count on a different path that will be free of Alliance entanglements.  The Horde conquest of Ashenvale is now in full swing!\n\nYou've earned your pay this day, hero.  I salute you!" } })
apply(217, { "classic", "forever" }, { deDE = { progress = "Grawmug und seine beiden Wachen, Knirscher und Muskelprotz, sind noch immer am Leben. Eure Mission ist nicht beendet, solange noch einer der drei am Leben ist. Das Zwergenreich zählt auf Euch, {name}!", completion = "Ganz ausgezeichnet, {name}! Ihr habt wieder Hoffnung an den Loch Modan gebracht. Jetzt, wo Grawmug tot ist, besteht eine größere Chance, dass die Troggs aus unserem Land vertrieben werden." }, enUS = { progress = "Grawmug and his two guards, Gnasher and Brawler, are still alive.  Your mission is not complete until all 3 have been brought to death.  The Dwarven empire is counting on you, {name}.", completion = "Most excellent, {name}!  You have brought hope to Loch Modan.  With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land." } })
apply(218, { "classic", "forever" }, { deDE = { progress = "{name}! Glück gehabt?", completion = "Großartig, {name}! Vielen Dank, dass Ihr mein Notizbuch zurückgeholt habt. Nun, es scheint, als sei das Trollproblem hier im Coldridgetal unter Kontrolle und als müssten wir uns nicht allzu viele Sorgen machen.\n\nNachdem ich meinem Bericht den letzten Schliff gegeben habe, werde ich jemanden brauchen, der ihn meinem Bruder Senir bringt." }, enUS = { progress = "{name}! Any luck?", completion = "Wonderful, {name}! Many thanks for retrieving my notebook. Well, it would seem that the troll situation here in Coldridge Valley is under control and not much cause for worry.\n\nAfter I put the finishing touches on my report, I'll need someone to courier it to my brother Senir." } })
apply(219, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Ihr habt dem Königreich gut gedient, {class}. Danke, dass Ihr Corporal Keeshan bei seiner Flucht vor den gefürchteten Orcs des Blackrockklans geholfen habt. Eure tapferen Taten an diesem Tag sollen nicht unbelohnt bleiben." }, enUS = { progress = "Yes?", completion = "You have served the Kingdom well, {class}.  Thank you for assisting Corporal Keeshan with his escape from those dreaded Blackrock Orcs.  You shall be rewarded for your brave acts this day." } })
apply(220, { "classic", "forever" }, { deDE = { progress = "Da seid Ihr ja wieder, {name}. Ihr seht gut aus.\n\nWas führt Euch schon so bald zu mir zurück?", completion = "Ah, eine Phiole mit Wasser, von Brine geschaffen und gesegnet und von keinem Geringeren eingesammelt als Euch selbst.\n\nDie Flüssigkeit in dieser Phiole ist das wichtigste Element, um ein Sapta für Euch herzustellen, doch sie findet auch für eine weitere Aufgabe Verwendung.\n\nMit dem Sapta, das ich für Euch herstelle, solltet Ihr die Wassergeister am Schrein im Silberwald, südlich von Undercity, sehen. Was die verbleibenden Tropfen betrifft, nun, zu den verbleibenden Tropfen sage ich Euch etwas, sobald Ihr glaubt, dass Ihr bereit seid.\n\nSeid Ihr auf eine weitere Reise vorbereitet, {name}?" }, enUS = { progress = "Hello again, {name}. You're looking well.\n\nWhat brings you back to me so soon?", completion = "Ah, a vial of water created and blessed by Brine, and gathered by you, no less.\n\nThe liquid in this vial will be key in creating a sapta for you, but also used in one other task.\n\nThe sapta I create for you should be used to see the water spirits at the shrine in Silverpine Forest, south of the Undercity. The remaining drops, well, the remaining drops I will tell you about if you feel you are ready.\n\nAre you prepared for one more journey, {name}?" } })
apply(221, { "classic", "forever" }, { deDE = { progress = "Schon zurück, {name}? Ich hoffe, Ihr seid nicht gekommen, um mir zu sagen, dass Ihr aufgegeben habt?", completion = "Gegen die Dunkelläufer habt Ihr Euch gut geschlagen, {name}. Aber es scheint, als sei ihre Zahl schier unerschöpflich. Ganz gleich, wie viele wir töten, es schießen immer mehr aus dem Boden, um ihre Reihen wieder zu schließen.\n\nWelche böse Macht zieht sie nur hierher? Warum sind sie gekommen, um unser unglückliches Land zu plagen?\n\nDoch ich vertraue auf Meister Carevin. Zweifellos wird er der Sache auf den Grund kommen." }, enUS = { progress = "Back so soon, {name}? I hope you haven't come to tell me you've given up.", completion = "You performed well against the Dark Runners, {name}. But it seems as though their numbers are inexhaustible. Every time we make progress, more spring up to refill their ranks.\n\nWhat is the evil power that draws them here? Why have they come to disturb our unhappy realm...\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem." } })
apply(222, { "classic", "forever" }, { deDE = { progress = "Furchterregende Biester, nicht wahr? Doch fürchtet Euch nicht, {name}, die, die für das Licht kämpfen, werden niemals fallen!", completion = "Ich will ganz ehrlich mit Euch sein, {name}. Ich hatte nicht geglaubt, dass Ihr so weit kommen würdet. Aber ganz offensichtlich seid Ihr als {class} nicht zu unterschätzen. Und wenn Ihr Euch ganz offiziell Meister Carevins Sache anschließen wollt, dann verfasse ich gern ein Empfehlungsschreiben für Euch." }, enUS = { progress = "Intimidating beasts aren't they? But have no fear, {name}, those who stand for the Light will never fall!", completion = "{name}, to be honest with you, I did not believe that you would get this far, but you are clearly a {class} to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation." } })
apply(223, { "classic", "forever" }, { deDE = { progress = "Ja, was wollt Ihr? Macht schnell, es gibt wichtige Dinge, um die ich mich kümmern muss.", completion = "Vergebt mir den kühlen Empfang, {name}, aber wie Ihr sicher sehen könnt, bin ich ein viel beschäftigter Mann. Ganz offensichtlich habt Ihr Calor beeindruckt - ich kann Euch versichern, das ist eine beachtliche Leistung - und er hat Euch seine Empfehlung ausgesprochen.\n\nEs sind äußerst üble Gestalten unterwegs, {name}, und wir können die Hilfe von jedem gebrauchen, der seinen Wert bewiesen hat. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen Hilfe gewähren. Seid wachsam, seid auf der Hut und traut niemandem, der unserer Sache nicht unterstützt.\n\nRuhm unter dem Licht!" }, enUS = { progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, {name}, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, {name}, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light." } })
apply(225, { "classic", "forever" }, { deDE = { completion = "Morgan Ladimore?\n\nAber ja, natürlich. Seine Geschichte ist lang und traurig. Ich kannte ihn gut, ehe er in den Krieg zog, doch das war das letzte Mal, dass ich ihn gesehen habe. Er war ein guter und edler Mann, doch es nahm ein böses Ende mit ihm.\n\nEinen Moment, ich glaube, ich habe hier etwas, das Euch die Geschichte besser erzählen kann als meine eigene Erinnerung..." }, enUS = { completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections..." } })
apply(226, { "classic", "forever" }, { deDE = { progress = "Seid Ihr immer noch auf der Wolfsjagd?", completion = "Oh, gut. Ihr habt das Rudel ganz schön reduziert. Und nachdem uns diese Wölfe jetzt nicht mehr an den Fersen hängen, können wir uns wieder damit beschäftigen, wie wir mit Morbent Fel fertig werden.\n\nHier, nehmt ein paar von diesen Blitzstrahlbündeln. Sie werden in der Stadt hergestellt und Sven hat etliche davon geschenkt bekommen, um ihn in seiner Sache zu unterstützen." }, enUS = { progress = "You still hunting wolves...?", completion = "Oh good.  You thinned out that pack quite a bit, and without those wolves nipping out our heels, we can bind our minds to dealing with Morbent Fel.\n\nHere, take some of these Flash Bundles.  They make them in town, and a lot have been donated to Sven to help with his cause." } })
apply(227, { "classic", "forever" }, { deDE = { completion = "Morgan Ladimore? Nie gehört.\n\nOh, Ihr meint Mor'Ladim! Dann nehme ich an, Ihr kennt die Geschichte nicht?\n\nNun gut, ich gebe Euch die Kurzfassung. Im Dämmerwald wandert seit einiger Zeit ein wandelnder Untoter namens Mor'Ladim herum. Nach allem, was wir herausfinden konnten, scheint dies der untote Körper von Morgan Ladimore zu sein, von dem Ihr offenbar gehört habt. Er bereitet uns alle möglichen Probleme, greift patrouillierende Wachmänner an und tötet Leute.\n\n<Sie mustert Euch prüfend.>\n\nIhr seht mir fähig genug aus; vielleicht könnt Ihr ihn ja zur letzten Ruhe betten." }, enUS = { completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A wandering undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest." } })
apply(228, { "classic", "forever" }, { deDE = { progress = "Ich kann es verstehen, wenn Ihr Probleme mit ihm habt, {name}. Wir haben einige unserer besten Behüter an Mor'Ladim verloren.", completion = "Ihr habt ihn getötet? Das ist eine beachtliche Leistung, {name}! Im Namen der Bewohner von Dunkelhain und im Namen der Nachtwache danke ich Euch.\n\nÄh, da wäre allerdings noch eine kleine Sache..." }, enUS = { progress = "I don't blame you if you're having trouble with him, {name}. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, {name}! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however..." } })
apply(229, { "classic", "forever" }, { deDE = { completion = "Ja? Mein Vater...\n\n<Sie schlägt die Augen nieder.>\n\nIch wünschte... ich wünschte, es gäbe etwas, das ich für ihn hätte tun können... Wenn ich nur mit ihm gesprochen hätte, ehe er..." }, enUS = { completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he..." } })
apply(230, { "classic", "forever" }, { deDE = { progress = "Ihr habt was gefunden? Bitte zeigt es mir...", completion = "<Sven liest in dem Buch, dann schlägt er es heftig zu.>\n\nDie schattenhafte Gestalt, die ich sah, war Zeuge, wie meine Familie um's Leben kam! Es gibt da etliche Fragen, die ich diesem Mann gern stellen würde... wenn ich nur wüsste, wer er ist!" }, enUS = { progress = "You found what??  Please, let me see it...", completion = "<Sven reads the book's pages, then slams it shut.>\n\nThat shadowy figure I saw was a witness to my family's death!  There are questions I'd like to ask that man...if only I knew who he was!" } })
apply(231, { "classic", "forever" }, { deDE = { progress = "Lasst mich in Ruhe...", completion = "<Eine geisterhafte Stimme ertönt im Wind.>\n\nIst das...? Sarah? Kann es sein? Ist sie tatsächlich noch am Leben? Die Last fällt von meinen Schultern...\n\n{name}. Nehmt Archeus, mein Schwert. Jetzt, wo meine Seele ihren Frieden findet, brauche ich es nicht mehr. Es wurde geschmiedet, um Gutes zu tun, und obgleich ich selbst mich als unwürdig erwiesen habe, es zu tragen, werdet vielleicht Ihr das Licht durch es verbreiten.\n\nLys, meine Liebste..." }, enUS = { progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n{name}. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love..." } })
apply(232, { "classic", "forever" }, { deDE = { progress = "Ja, womit kann ich Euch helfen? Seid Ihr hier, um Geschäfte im Namen der Königlichen Apothekenvereinigung zu machen oder seid Ihr nur hergekommen, um meinen Tag zu verschönern?", completion = "Ah, Zinge benötigt ein Set, was? Es betrübt mich, dass Zinge mich nicht mit ihrem holden Anblick selbst beehrt.\n\nNun gut, ich werde Euch ein Set beschaffen." }, enUS = { progress = "Yes, and what may I assist you with?  Are you here on business for the Royal Apothecary Society, or have you arrived here merely to brighten my day?", completion = "Ah, Zinge needs a kit, does she?  It saddens me that Zinge does not choose to grace myself with her sweet presence.\n\nVery well, let me procure a kit for you." } })
apply(234, { "classic", "forever" }, { deDE = { progress = "Kann ich Euch behilflich sein?", completion = "Ah, ausgezeichnet. Es ist schon eine Weile her, dass ich Nachricht aus Ironforge hatte." }, enUS = { progress = "Is there something I can help you with?", completion = "Ahh, excellent. It's been a while since I received word from Ironforge." } })
apply(235, { "classic", "forever" }, { deDE = { completion = "Willkommen an der neuen Grenze, {name}. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, {class}, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst." }, enUS = { completion = "Welcome to the new frontier, {name}.  Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know." } })
apply(237, { "classic", "forever" }, { deDE = { progress = "Wir brauchen mehr Zeit, {race}. Ihr habt den Befehl, 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher zu töten. Setzt den Feind unter Druck, bis wir Verstärkung erhalten. Jetzt ist nicht die Zeit für Müßiggang.", completion = "Ihr habt Eure Mission gut erfüllt, {race}. Der König selbst wäre stolz auf Euch.\n\nDie Verstärkung, die uns versprochen war, ist jedoch nie angekommen. Anscheinend ist die Front der Allianz getränkt von dem roten Blut unserer gefallenen Brüder. Die Nachricht von diesen Verlusten hinterlässt einen bitteren Nachgeschmack. Doch wir dürfen nicht zulassen, dass ihr Tod vergeblich war. In diesen finsteren Zeiten müssen wir zusammenstehen und den Ruhm der Allianz wieder aufleben lassen.\n\nSprecht wegen Eurer nächsten Aufgabe mit Gebirgsjäger Wallbang. Wir brauchen Euch jetzt mehr als je zuvor." }, enUS = { progress = "We need more time, {race}.  Your orders are to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Keep the enemy under pressure until we are granted reinforcements.  This is no time for idle behavior.", completion = "You accomplished your mission well, {race}.  The King himself would be proud.\n\nThe reinforcements promised to us never showed, however.  Apparently the Alliance front is a sea of crimson from the blood of our fallen brethren.  The news of the losses leaves a bitter taste in one's mouth.  But we must not let their deaths go for naught.  We must rally in these grim times and bring glory back to the Alliance.\n\nSpeak with Mountaineer Wallbang for reassignment.  You're needed now more than ever." } })
apply(238, { "classic", "forever" }, { deDE = { progress = "Ja, ich denke, Luca ist genauso beunruhigt wie Ihr. Aber es macht keinen Unterschied - gebt mir das Feldprobenset. Ich muss daran einige Veränderungen vornehmen, damit eine Suche nach den geeigneten Grundmaterialien möglich ist.\n\nIhr habt das Set doch, nicht wahr?", completion = "Gut - es freut mich, mit jemandem zu arbeiten, der darauf achtet, nicht meine Zeit zu verschwenden.\n\nNachdem ich einige Veränderungen an diesem Set vorgenommen habe, könnt Ihr euch auf den Weg machen. Ihr werdet damit einige wichtige Daten für die Aufgabe sammeln, die vor uns liegt.\n\nEs dauert nur einen Augenblick, um diese Veränderungen abzuschließen. Während Ihr wartet, solltet Ihr vielleicht schon einmal darüber nachdenken, was Ihr in die Wüste mitnehmen wollt.\n\nJa, ich sagte \"Wüste\"." }, enUS = { progress = "Yes, I think Luca is as disturbing as you do.  It matters not - hand me the field sampling kit.  I will need to make some adjustments to it in order to survey for the proper base materials.\n\nYou have the kit, don't you?", completion = "Good - it pleases me to be working with someone who takes pride in not wasting my time.\n\nAfter I make some adjustments to this kit, you'll be ready to head out into the field.  You'll be using it to collect some vital data to the task at hand.\n\nIt will take just a moment for me to finish the modifications.  While you are waiting, you should probably start thinking about what you'd like to bring to the desert with you.\n\nYes, I said the desert." } })
apply(239, { "classic", "forever" }, { deDE = { completion = "Marshal Dughan hat Euch geschickt, wie? Ihr seid zwar nicht in der Armee, aber wenn Dughan Euch geschickt hat, dann soll mir das recht sein.\n\nUnsere Lage hier ist, um es gelinde auszudrücken, angespannt. Ich hoffe, Ihr könnt ein wenig aushelfen." }, enUS = { completion = "Marshall Dughan sent you, eh?  Well you're not from the army, but if Dughan sent you then that's good enough for me!\n\nOur situation is, to say the least, a stressed one.  I hope you can give us a hand." } })
apply(240, { "classic", "forever" }, { deDE = { progress = "Da seid Ihr ja, {name}! Habt Ihr mein Essen gebracht?", completion = "Ah! Danke, {name}. Die waren jetzt genau richtig!\n\nUnd hier, bitte gestattet, dass ich Euch dafür bezahle!" }, enUS = { progress = "{name}, you're here!  Do you have my food?!?", completion = "Aha!  Thank you, {name}.  Those really hit the spot!\n\nAnd here, please let me pay you for these!" } })
apply(244, { "classic", "forever" }, { deDE = { completion = "Rotkammgnolle so nah an Elwynn? Es ist möglich, dass sie kurz vor einem Einfall in unsere Heimat stehen. Bald werden die Bewohner von Seenhain nicht die einzigen Menschen sein, die belagert werden!\n\nHier ist Euer Lohn, auch wenn Ihr uns schlechte Nachrichten bringt. Und es kommt auch noch zu einem schlechten Zeitpunkt, denn wir sind nicht gut dafür gerüstet." }, enUS = { completion = "There are Redridge gnolls that close to Elwynn??  They may be poised to advance into our homeland.  Soon the people of Lakeshire may not be the only humans under siege!\n\nHere is your pay, though you bring us dire news.  And it comes at a bad time, for we are ill equipped to deal with it." } })
apply(245, { "classic", "forever" }, { deDE = { completion = "Ah! Ihr seid zurück. Und Ihr seht gar nicht sonderlich angeschlagen aus, scheint mir. Natürlich ist die Nachtwache dankbar für Eure Arbeit, {name}, und ich hatte Euch ja auch eine Belohnung versprochen. Hier bitte." }, enUS = { completion = "Ah! You're back. And not too much worse for wear, it'd seem. Of course, {name}, the Night Watch is grateful for your work, and I did promise you a reward, so here." } })
apply(246, { "classic", "forever" }, { deDE = { progress = "Bitte entschuldigt, {name}, aber wir haben hier jede Menge zu tun. Wenn Ihr nichts zu berichten habt, dann muss ich meine Aufmerksamkeit anderen Dingen zuwenden.", completion = "<Deputy Feldon hört sich Euren Bericht an.>\n\nDann lagert dort eine beachtliche Streitmacht Gnolle und nach dem, was Ihr mir erzählt habt, sind sie auch zäh. Es kann nicht leicht für Euch gewesen sein, diese Informationen zu beschaffen.\n\nHier, bitte schön, {name}. Wir danken Euch für Eure Hilfe.\n\nUnd falls Ihr es noch nicht getan habt, sprecht in Seenhain auch mit Marshal Marris und Magistrat Solomon. Unsere Situation wird immer verzweifelter - die beiden werden Euch brauchen können, da bin ich mir sicher." }, enUS = { progress = "Excuse me, {name}, but we have a lot to keep our hands tied here.  If you have nothing to report, then I must put my mind to other matters.", completion = "<Deputy Feldon listens to your report...>\n\nThere's a sizable force of gnolls encamped there, and from what you tell me they are tough ones.  It must not have been easy for you to gather this intelligence.\n\nHere you are, {name}.  We are grateful for your aid.\n\nAnd if you haven't already done so, speak with Marshal Marris and Magistrate Solomon within Lakeshire.  Our situation grows ever more desperate - those two will have need of you I'm sure." } })
apply(248, { "classic", "forever" }, { deDE = { progress = "Dieser Krug war einmal mit übel riechendem Schnaps gefüllt. Jetzt liegt er leer und vergessen auf ein paar Fässern.", completion = "Dies ist ein passendes Gefäß für die Glyphe von Azora, sodass Theocritus in den Geist der Bewohner von Burg Steinwacht eindringen kann." }, enUS = { progress = "This jar once held a foul-smelling liquor, but now lies empty and forgotten on a pair of barrels.", completion = "It is a suitable vessel for the Glyph of Azora, allowing Theocritus to delve into the minds within Stonewatch Keep." } })
apply(249, { "classic", "forever" }, { deDE = { progress = "Sputet Euch, {name}, ehe meine Befürchtungen sich bewahrheiten und Morganths Macht sich ausweitet!", completion = "Ihr habt Eure Sache gut gemacht, {name}. Die Niederlage des Hexenmeisters Morganth hat Stormwind vor einer großen Gefahr bewahrt.\n\nDemütig biete ich Euch diese Belohnung an. Und ich würde Euch Frieden wünschen, wenn dies friedliche Zeiten wären.\n\nDoch stattdessen wünsche ich Euch Glück für die Aufgaben, die vor Euch liegen, und Sieg in den Kämpfen, die Ihr bestehen müsst." }, enUS = { progress = "Hurry, {name}, before my fears of Morganth spreading his power are made real!", completion = "You have done well, {name}.  In defeating the warlock Morganth, Stormwind is saved from a grave peril.\n\nI offer you this reward most humbly.  And I would bid you peace, if these were peaceful times.\n\nBut instead, I will bid you luck with your trials, and victory in the conflicts ahead." } })
apply(250, { "classic", "forever" }, { deDE = { completion = "Das verdächtig aussehende Fass enthält ein sonderbar riechendes Pulver." }, enUS = { completion = "The suspicious looking barrel contains a strange smelling powder." } })
apply(251, { "classic", "forever" }, { deDE = { progress = "Eine Nachricht von Calvinius, dem Einsiedler, wie? Ich kenne ihn nicht persönlich, aber wenn er draußen am Friedhof lebt, dann weiß ich, dass sein Gehirn verfault sein muss!", completion = "<Sirra beginnt, die Notiz zu übersetzen.>" }, enUS = { progress = "A note from Abercrombie the hermit, eh?  I don't know him, though if he lives out at the graveyard then I do know his brains have rotted out!", completion = "<Sirra begins translating the note...>" } })
apply(252, { "classic", "forever" }, { deDE = { progress = "Ah, ist die Notiz fertig übersetzt? Bitte, zeigt sie mir...", completion = "<Ello liest den Brief und wird kreidebleich. Dann sieht er Euch an.>\n\nIhr mögt Calvinius vielleicht aus Freundlichkeit geholfen haben. Doch dank Eurer Taten ist unsere Stadt verloren.\n\n<Ello versinkt in Gedanken...>" }, enUS = { progress = "Ah, is the note translated?  Please, let me see it...", completion = "<Ello reads the letter...and his face goes white.  He then looks at you...>\n\nAlthough the aid you gave Abercrombie may have been motivated from kindness, your actions have doomed our town.\n\n<Ello becomes lost in his thoughts...>" } })
apply(253, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Elizas Grab schon gefunden? Habt Ihr das Herz des Einbalsamierers?", completion = "Ihr habt es geschafft! Dank der ihm innewohnenden Magie ist das Herz gegen das Böse des Einbalsamierers gefeit und stellt somit einen mächtigen Schutz für die Stadt Dunkelhain dar.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, {name}. Euer Name wird für alle Zeit in unseren Annalen verzeichnet sein." }, enUS = { progress = "Have you yet found Eliza's grave?  Do you have the Embalmer's heart?", completion = "You've done it!  The magic within his heart will be proof against the Embalmer's evil, and a powerful aegis over the town of Darkshire.\n\nYou have done a great thing for our people, {name}.  Your name will remain in our annals forever." } })
apply(255, { "classic", "forever" }, { deDE = { completion = "Ah, das sind ausgezeichnete Neuigkeiten! Ich selbst und die Bewohner von Thelsamar wissen Eure Mühen außerordentlich zu schätzen. Und was noch besser ist: Wenn wir in der Lage sind, das Ogerproblem zu lösen, dann können wir unsere Aufmerksamkeit endlich auf diese vom Licht verlassenen Troggs richten." }, enUS = { completion = "Ah, this is excellent news! Your efforts are greatly appreciated by myself and the people of Thelsamar. Better yet, if we can solve the ogre problem, we'll be able to shift our focus to those Light-burning troggs." } })
apply(256, { "classic", "forever" }, { deDE = { progress = "Ja? Kann ich Euch behilflich sein?", completion = "Pfui! Was ist das denn? Und warum bringt Ihr...\n\nVerdammt! Kann es sein? Da verbrenn mich doch das Licht; ist das der Kopf dieses verdammten Ogers? Da habt Ihr vielleicht einen Fang gemacht! Hier, nehmt diese Belohnung, zusammen mit meinem Dank und dem der Bewohner von Thelsamar." }, enUS = { progress = "Yes? Is there something I can do for you?", completion = "Yech! What is that thing? And why would you bring it...\n\nBloody--! Is it? Well, Light burn me, is that the head of that bloody ogre? This certainly is a catch then! Here, your reward and the thanks of myself and the people of Thelsamar." } })
apply(257, { "classic", "forever" }, { deDE = { progress = "Kein Glück gehabt? Macht Euch nix draus, Pupserer...\n\nNicht jeder kann so gut sein wie ich.", completion = "Wie jetzt, Ihr hattet Erfolg?\n\nGlaubt mir, Eisenberndama, das sollte Euch nicht zu Kopf steigen. Denn jeder milchgesichtige Junge mit einem Bogen hätte so... kleine Exemplare töten können. Und ich hoffe, es hat Euch nicht zu viel Spaß gemacht, die Bussarde zu erschießen. Wir wollen doch nicht, dass sie aussterben! \n\nAch so, ähhhm... Es soll keiner sagen, dass Daryl der Kühne sein Wort nicht hält." }, enUS = { progress = "No luck? Don't feel too bad, Bolerroer...\n\nNot everyone can be me.", completion = "What? Success?\n\nTake it from me, Airtzama, you don't let it get to your head. I mean, any unshaven boy with a bow could have killed such... small specimens. And I hope you don't enjoy killing the buzzards so much, yes? We wouldn't want them to become extinct. \n\nWell, err... Never let it be said that Daryl the Bold would not hold to his word." } })
apply(258, { "classic", "forever" }, { deDE = { progress = "Es ist ganz normal, dass man sich selbst bemitleidet, wenn man sich vor jemandem blamiert, der so viel jünger ist als man selbst. Macht Euch nichts draus, Rinovaah...\n\nWie? Hab ich mir Euren Namen falsch gemerkt?", completion = "Ihr seht etwas mitgenommen aus. Die Eber haben Euch wohl ein paar Schwierigkeiten gemacht, wie? Keine Sorge, ich verrate es auch keinem, dass Ihr versagt habt; ich kann mir vorstellen, wie schwer es für Euch sein muss, auch ohne dass sich die Leute über Euch das Maul zerreißen.\n\nOh! Ihr habt es geschafft? Ihr habt die Eber getötet? Ich... also... na ja, das überrascht mich nicht! Jedes Kind hätte das - Wette?\n\nWas für eine Wette?" }, enUS = { progress = "It's only natural to feel sorry for yourself when shown up by someone so new to this world. You shouldn't feel bad, Airtzah.\n\nHm? Did I get your name wrong?", completion = "You seem a bit worse for wear. No doubt the boars gave you some trouble, hm? No worries, I will be discreet about your struggle, I can imagine how hard it must be for you without the accusations of wagging tongues.\n\nOh! You managed to kill the boars? I... well, that is... that is to say, I'm not surprised! Any child could have--bet?\n\nWhat bet?" } })
apply(261, { "classic", "forever" }, { deDE = { progress = "Die Geißel gewinnt mit jedem Tag an Stärke. Wenn Ihr ihren Vormarsch wirklich aufhalten wollt, dann beweist es mir.", completion = "Ihr habt Eure Entschlossenheit bewiesen, und der scharlachrote Kreuzzug lobt Euch dafür.\n\nWenn Ihr nicht vor rechtschaffenem Gemetzel zurückschreckt, dann ist Euer Pfad vielleicht der unsrige..." }, enUS = { progress = "The Scourge grows in power with the passing of each day.  If you truly wish to halt its advances, then show me.", completion = "You have proven your resolve, and the Scarlet Crusade commends you.\n\nIf you do not shy from righteous slaughter, then perhaps your path lies with us..." } })
apply(262, { "classic", "forever" }, { deDE = { progress = "Wenn Ihr einen Gegenstand von der Schattengestalt habt, nach der Ihr sucht, dann zeigt ihn mir. Ich kann vielleicht etwas über seinen Besitzer erspüren.", completion = "Hmm... Jemand hatte dieses Buch erst vor kurzem in der Hand, jemand, der von Rache getrieben wird. Allerdings sind die daran verbliebenen Eindrücke, oder zumindest die Eindrücke von seinem ursprünglichen Besitzer, sehr schwach.\n\nIch kann jedoch sagen, dass der ursprüngliche Besitzer dieses Buches kein Einheimischer von Dunkelhain ist." }, enUS = { progress = "If you have something that belongs to the shadowy figure for whom you seek, then let me see it.  I may be able to divine something of its owner.", completion = "Hmm... Someone handled this book recently, someone who is driven by revenge.  But the impressions left on it, at least the impressions from the original owner, are faint.\n\nI can tell, however, that the original owner of this book is not a native of Darkshire." } })
apply(264, { "classic", "forever" }, { deDE = { progress = "Der Stein fühlt sich kalt an, wurde aber offensichtlich zweckentfremdet. Überall liegt Abfall herum; Scharten und Risse überziehen das Relief auf dem Sarg; und das Gestrüpp ringsherum hat schon begonnen, die Stätte zu überwuchern.\n\nNiemand kümmert es, wer hier begraben liegt, am allerwenigsten etwaige Opfer der Seuche.", completion = "Ihr legt den wertlosen Anhänger auf das Grab, und der darin eingelassene Edelstein scheint merklich zu verblassen.\n\nAls Ihr aufsteht, um zu gehen, seht Ihr auf den Anhänger herab. Er liegt leblos über den Händen des Reliefs, das in die Oberseite des Sarges eingehauen ist. Eure Gedanken werden kurz unterbrochen, als ein steifer, kalter Windhauch über das Grabmal weht. Für einen Moment ist alles um Euch herum still." }, enUS = { progress = "The stone is cold to the touch,  but has obviously been abused. Trash litters the area; nicks and gashes decorate the relief atop the coffin; and the foliage around the grave has started to grow over the site.\n\nNo one cares for whoever is buried here, especially not any victims of the plague.", completion = "You place the worthless pendant on the grave, and the gemstone within the setting seems to dull noticeably.\n\nAs you stand to leave, you look down at the pendant; it lies lifelessly over the hands of the relief sculpted into the top of the coffin. Your thoughts are interrupted by a stiff, cool breeze passing over the Sepulcher. For a moment everything around you is silent." } })
apply(265, { "classic", "forever" }, { deDE = { progress = "Manchmal verkaufe ich leere Bücher an Gelehrte oder Magier oder an irgendwen, der ein Tagebuch führen möchte.\n\nIch kann mich gut an jeden erinnern, dem ich in den letzten paar Monaten ein Buch verkauft habe...", completion = "Ach ja. Ich habe dieses Buch vor einem Monat an eine zwielichtige Type verkauft. Er hat mir seinen Namen nicht gesagt, aber er war ein nervöser, hektischer Kerl, der laufend über seine Schulter sah.\n\nIch hoffe, das hilft Euch weiter..." }, enUS = { progress = "Sometimes I'll sell blank books to scholars and mages, or to anyone who wants to keep a journal.\n\nI remember well everyone to whom I sold a book within the last few months...", completion = "Ah, yes.  I sold this book a month ago to a shady person.  He didn't tell me his name, but he was a nervous, jittery chap, always looking over his shoulder.\n\nI hope that helps you..." } })
apply(266, { "classic", "forever" }, { deDE = { progress = "Der Rote Rabe läuft nicht mehr so gut wie früher, aber hier kommen immer noch Reisende durch.\n\nWenn Ihr mir die Person beschreibt, nach der Ihr sucht, dann erinnere ich mich vielleicht an sie.", completion = "Oh ja, ich erinnere mich an dieses Buch. Sein Besitzer mietete sich hier für ein paar Tage ein und verbrachte die Abende schreibend an der Bar.\n\nEr verließ die Stadt überhastet und brummelte dabei etwas darüber, dass er gejagt würde von... irgendetwas. Als ich ihn das letzte Mal sah, verließ er die Stadt in Richtung Westen, auf der Suche nach einem neuen Versteck.\n\nDer erste Ort, in dem er landen würde, wäre Rabenflucht." }, enUS = { progress = "The Scarlet Raven doesn't see the business it used to, but we still do get travelers passing through.\n\nIf you can describe the person you're looking for, maybe I'll remember him.", completion = "Oh yeah, I remember this book.  Its owner rented a room for a few days, and spent his nights at the bar, writing.\n\nHe left town in a hurry, muttering about being hunted by...something.  Last I saw him he was heading west out of town, looking for a new spot to hide.\n\nThe first place he'd find to the west is Raven Hill..." } })
apply(267, { "classic", "forever" }, { deDE = { progress = "Könnt Ihr mir 8 Trogg-Steinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, {name}.", completion = "Ich bin ziemlich beeindruckt, {name}. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebeard wäre stolz auf Euch!" }, enUS = { progress = "Do you have 8 Trogg Stone Teeth to show me?  If not, there is still work to be done, {name}.", completion = "I am quite impressed, {name}.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!" } })
apply(268, { "classic", "forever" }, { deDE = { progress = "Habt Ihr herausgefunden, wer die Schattengestalt war?", completion = "Dieses Tagebuch macht mir vieles klar und zeigt mir den Weg, den ich gegen die dunklen Reiter zu gehen habe! Ich habe diese Reiter im Dämmerwald und im Gespräch mit dem Zauberer Morbent Fel am verlassenen Gut gesehen." }, enUS = { progress = "Did you find who the Shadowy Figure was?", completion = "This journal explains much to me, and sets me on the path against the dark riders!  I have seen these riders in Duskwood, and have seen them speak with the wizard Morbent Fel, at the Forlorn Rowe." } })
apply(269, { "classic", "forever" }, { deDE = { progress = "Ruht Euch erst einmal aus, Bruder. Ich sehe Euch an, dass Ihr weit gereist seid und eine schwere Bürde tragt. Könnt Ihr mir erzählen, was diesen dunklen Schatten über Euch wirft?", completion = "<Nachdem er das Tagebuch gelesen und Eure Absichten erfahren hat... >\n\nEine böse Besudelung hat im ohnehin bereits belagerten Dämmerwald Fuß gefasst. Ich danke dem Licht, dass wir einen Helden wie Euch haben, der sich ihm stellen will.\n\nAber zuerst müsst Ihr Euch auf die kommenden Strapazen vorbereiten... denn der Totenbeschwörer Morbent Fel ist ungeheuer mächtig, und er hat dunkle Verzauberungen auf sich selbst gewirkt, um sich vor körperlichen Angriffen zu schützen. Wenn Ihr ihn besiegen wollt, werdet Ihr eine Waffe benötigen, die gegen diese Schutzzauber gefeit ist." }, enUS = { progress = "Rest, brother.  I can tell you have traveled far, and you bear a heavy burden.  Can you tell me what casts that dark shadow over you?", completion = "<After reading the journal and hearing your intent...>\n\nAn evil taint has gained a foothold within the already beleaguered Duskwood.  I thank the Light we have a hero such as you to face it.\n\nBut you must first prepare yourself for the coming trial...for the Necromancer Morbent Fel is immensely powerful, and has cast dark enchantments about himself to protect him from physical assaults.  If you are to defeat him, you will need a weapon that is proof against these protections." } })
apply(270, { "classic", "forever" }, { deDE = { completion = "Lichtgeschmiedetes Eisen ist ein wertvolles Metall, aber es scheint, als hättet Ihr eine schreckliche Aufgabe vor Euch. Ihr seid weit gereist, Bruder. Mit Glück findet Ihr aber gerade das, was Ihr sucht!\n\nUnd falls Ihr das Eisen findet: Ich kenne da jemanden, der es zu einer Waffe gegen den Totenbeschwörer im Dämmerwald, von dem Ihr redet, formen kann." }, enUS = { completion = "Lightforge Iron is a precious metal, but it sounds like your quest is a dire one.  You've come a long way, Brother.  With luck, you might just find what you seek!\n\nAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood." } })
apply(271, { "classic", "forever" }, { deDE = { progress = "Ah, {name}! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n<Er fährt unbewusst mit einem Finger an seiner Narbe entlang>\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n<Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.>\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!" }, enUS = { progress = "Ah, {name}! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks at it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!" } })
apply(272, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, {name}? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, {name}... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt." }, enUS = { progress = "Have you formed your pendant for me to inspect, {name}?  If you need help in locating the parts, try asking the local populace for information.  Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, {name} - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form." } })
apply(273, { "classic", "forever" }, { deDE = { completion = "Hmpf, es wird mehr als einen Überfall durch die Dunkeleisenzwerge brauchen, um die Lieferungen zu stoppen!\n\nAber Saean... Ich hätte nie vermutet, dass er einer ihrer Sympathisanten ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich die Anzeichen übersehen.\n\nNun ja, darüber werde ich später nachdenken." }, enUS = { completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later." } })
apply(274, { "classic", "forever" }, { deDE = { progress = "Was bringt Ihr da von Ashlan?", completion = "Eine Entschärfungspaste? Für Zephyrium? Oh Himmel!" }, enUS = { progress = "What is that you bring from Ashlan?", completion = "A disarming colloid? For Seaforium?  Oh heavens!" } })
apply(275, { "classic", "forever" }, { deDE = { progress = "Das Sumpfland weint noch, und die Moorkrabbler wüten noch. Kommt zurück, wenn Eure Aufgabe erledigt ist.", completion = "Das Leiden des Landes wurde durch Eure Taten gemildert, und dafür werde ich Euch belohnen." }, enUS = { progress = "The Wetlands still weep, and the Fen Creepers still rage.  Return to me when your task is done.", completion = "This land is soothed by your efforts, and for this I will grant you a boon." } })
apply(276, { "classic", "forever" }, { deDE = { progress = "Eure Aufgabe steht noch an, junger {class}.", completion = "Indem Ihr die Anzahl der Gnolle verringert habt, habt Ihr Euch um das Wohlergehen des Sumpflandes gekümmert. Obwohl mein Vertrauen in Euer Volk in der Vergangenheit belastet wurde, {race}, kann es vielleicht doch noch wieder hergestellt werden." }, enUS = { progress = "Your task is still at hand, young {class}.", completion = "By reducing the Gnolls' number, you have tended to the health of the Wetlands.  Although my faith in your people has been taxed in the past, {race}, it may yet be restored." } })
apply(277, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Feuermach-Werkzeuge der Gnolle?", completion = "... Danke. Ich werde diese Feuersteine zertrümmern und ins Meer werfen, auf dass sie nie wieder dazu verwendet werden können, lebendiges Holz zu verbrennen." }, enUS = { progress = "Do you have the Gnolls' tools for fire?", completion = "... thank you.  I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood." } })
apply(278, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die benötigten Dinge? Die Zeit drängt!!", completion = "Gerade rechtzeitig, {name}!" }, enUS = { progress = "Do you have the needed items?  Time is of the essence!!", completion = "Just in time, {name}!" } })
apply(279, { "classic", "forever" }, { deDE = { progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, {name}.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine." }, enUS = { progress = "Our merchants will not be safe until we are rid of Gobbler and those Murlocs.", completion = "Ah, well done {name}.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines." } })
apply(280, { "classic", "forever" }, { deDE = { progress = "Der Deckel des Fässchens schraubt sich langsam ab.", completion = "Das Fässchen zischt ein wenig, als sich die Entschärfungsmixtur darin löst." }, enUS = { progress = "The top of the keg slowly twists off.", completion = "The keg fizzles slightly as the Disarming Mixture settles in." } })
apply(281, { "classic", "forever" }, { deDE = { completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet einen Arm voll rot gefärbter Flaschen." }, enUS = { completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles." } })
apply(282, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Seid vorsichtig, {name}, der Tunnel nach Dun Morogh ist mit Troggs verseucht und nicht sicher zu bereisen.\n\nWenn Ihr keine eiligen Geschäfte in Dun Morogh zu erledigen habt, möchte ich Euch bitten, hier in Anvilmar zu bleiben, bis der Tunnel wieder sicherer ist.", completion = "Hm, nun gut, wenn Whitebeard Euch mit wichtigen Geschäften nach Dun Morogh schickt, kann ich Euch ja schlecht aufhalten, oder?\n\nLasst mich Euch wenigstens ein paar Ratschläge und Anweisungen geben." }, enUS = { progress = "Hail! Have a care, {name}, the tunnel to Dun Morogh is infested with troggs and is not safe for travel.\n\nIf you haven't any pressing business in Dun Morogh, I'll have to ask you to remain in Anvilmar until the tunnel is safer.", completion = "Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can't very well stop you, can I?\n\nAt least let me provide you with some advice and directions." } })
apply(283, { "classic", "forever" }, { deDE = { completion = "Vielen, vielen Dank, {name}! Ihr habt den Stonewroughtdamm gerettet! Ohne Eure Hilfe hätten die Terroristen der Dunkeleisenzwerge bestimmt für den Untergang dieses mächtigen Wahrzeichens gesorgt. Mit Eurer Tapferkeit habt Ihr das Königreich und die Allianz stolz gemacht, {class}.\n\nDer Damm ist wieder sicher ... zumindest vorläufig ..." }, enUS = { completion = "Thank you so much, {name}!! You have saved the Stonewrought Dam!  Without your help, the Dark Iron terrorists would have surely seen to this mighty landmark's demise.  You have made the Kingdom and the Alliance proud, brave {class}.\n\nThe Dam is once again safe. . . for the time being at least. . . ." } })
apply(284, { "classic", "forever" }, { deDE = { completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!" }, enUS = { completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!" } })
apply(285, { "classic", "forever" }, { deDE = { completion = "Dieses Fass ist unter Schlamm und Gras halb begraben..." }, enUS = { completion = "This barrel is halfway buried amidst the mud and grass ..." } })
apply(286, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Statuette?", completion = "Der Kapitän der Blind Princess wird erleichtert sein zu hören, dass seine kostbare Fracht geborgen wurde. Ihr habt Euch diesen Lohn durch die geleisteten Dienste wohl verdient.\n\nEs tut gut, verlässliche Leute wie Euch zu kennen, insbesondere in so beschwerlichen Zeiten wie diesen." }, enUS = { progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You have well earned this payment for services rendered.\n\nIt is good to see dependable folk like you, especially in trying times such as these." } })
apply(287, { "classic", "forever" }, { deDE = { completion = "Ah, {name}! Ich hätte nicht gedacht, dass Ihr Probleme hättet, dorthin zu finden. Meine Richtungsangaben sind vortrefflich, wisst Ihr...\n\nLasst mich gerade noch schnell meinen Bericht fertig stellen.\n\n\n\nHier! Nun, haha, ja, das ist jetzt wirklich lustig... Kann ich davon ausgehen, {name}, dass es Euch nichts ausmachen würde, mir einen letzten Gefallen zu tun?" }, enUS = { completion = "Ah, {name}! I didn't think you'd have much trouble finding the place, my directions are excellent, you know...\n\nLet me just finish up my report then.\n\n\n\nThere! Well, haha, now this certainly is funny... I don't suppose, {name}, that you would mind doing one last favor for me?" } })
apply(288, { "classic", "forever" }, { deDE = { progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!" }, enUS = { progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!" } })
